(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["video"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-make-a-video-text-to-video-generatio-2022"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-1\">一 · 在线服务现场：一次提示词请求如何压垮旧栈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-2\">二 · 旧栈的第二个死结：没有成对文本视频数据，条件注入无处落脚</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-3\">三 · 级联路径的推理形态与每段的代价归属</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-4\">四 · 长视频与流式：分块重叠把显存峰值钉在单块上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-5\">五 · 为什么非改不可：旧栈的三个不可调和项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-6\">六 · 级联栈的边界：当“先低分辨率再放大”撞上在线服务的显存墙</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-7\">七 · 请求形态的测量口径：把“一句提示词”拆成可计量的字段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-8\">八 · 长尾从哪里来：块数、重叠与流式的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-9\">九 · 负载如何塑造方案：批处理边界与条件复用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-10\">十 · 方案反过来限制负载：准入、截断与降级</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-11\">十一 · 可核查的监控面板：把机制翻译成指标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-12\">十二 · 级联栈的负载塑形：谁在决定批大小与块边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-13\">十三 · 从级联路径反推 kernel 热点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-14\">十四 · 精度阶梯：FP16 / BF16 / FP8 / NVFP4 各自落在哪一级</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-15\">十五 · 累加精度与误差传播的公式拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-16\">十六 · Blackwell 特性如何落到这些 kernel 上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-17\">十七 · 一个可执行的精度配置与监控闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-18\">十八 · 级联扩散的精度边界：低精度能省在哪、会坏在哪</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-19\">十九 · 显存账本的三类占用与峰值判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-20\">二十 · KV 与跨步缓存的真实形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-21\">二十一 · 分块、重叠与卸载的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-22\">二十二 · HBM3e 容量怎么算，带宽瓶颈在哪</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-23\">二十三 · 一个可复算的显存预算示例</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-24\">二十四 · 失败模式与监控项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-25\">二十五 · 级联栈的批处理边界：三阶段各自能批，但不能同批</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-26\">二十六 · 连续批处理与 chunked prefill 在扩散采样上的映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-27\">二十七 · 优先级与抢占：谁该被切，切在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-28\">二十八 · 分离式预填/解码在级联栈里的对应物</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-29\">二十九 · 尾延迟怎么压：从块粒度到 SLO 预算分配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-30\">三十 · 跨阶段一致性监控与调度的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-31\">三十一 · 级联栈的切分面：为什么不能只按参数量分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-32\">三十二 · 集合通信的三种形态与各自的代价位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-33\">三十三 · NVLink 5 与 NVSwitch：域内通信的边界在哪</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-34\">三十四 · NIXL 传输：跨阶段与跨节点的潜变量搬运</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-35\">三十五 · 通信何时成为瓶颈：三个可观测的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-36\">三十六 · 精度与切分的交互：低精度不改变通信拓扑，但改变阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-37\">三十七 · 精度塌陷：从潜变量到像素的误差放大链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-38\">三十八 · OOM 与显存峰值：峰值不在你以为的地方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-39\">三十九 · 批抖动与尾延迟：级联各阶段的批不同步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-40\">四十 · 接缝与运动不一致：静默降级的两种形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-41\">四十一 · 监控面与回滚路径：把配置做成可回退的开关</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-42\">四十二 · 级联栈的失效边界：从潜变量耦合到块间接缝</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-43\">四十三 · 基准口径的拆解：把一次请求切成可计量的段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-44\">四十四 · 硬件档位与精度：材料未给，口径必须先声明</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-45\">四十五 · batch 与并发：级联各段的批语义并不相同</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-46\">四十六 · 指标怎么读：TTFT/TPOT 的类比与视频特有的量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-47\">四十七 · 哪些提升不可比：四类典型陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-48\">四十八 · 落到可执行的口径表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-49\">四十九 · 迁移到别的模型：先看级联契约是否成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-50\">五十 · 迁移到别的领域：时间一致性的约束强度决定改法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-51\">五十一 · 规模上限在哪：三处代价的耦合决定天花板</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-52\">五十二 · 精度迁移的边界：低精度不能无差别套用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-53\">五十三 · 不适用的部署形态：流式与离线共享同一套假设</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-make-a-video-text-to-video-generatio-2022-sec-54\">五十四 · 工程判断：迁移前先测三条曲线</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:577px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 577.0 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"495.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">文本编码器将提示词转为条件嵌入，作为各级生成模块的条件输入。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"495.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">基础视频生成器在低分辨率潜空间执行多步扩散采样，输出粗视频潜变量。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"495.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">时空超分模块在时间维与空间维同时放大，复用低分辨率条件以减少重复采样。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"495.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">帧插值模块在相邻帧间生成中间帧，提升输出帧率并保持运动连续。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"495.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">三维 VAE 解码将潜变量还原为像素视频，按分块与重叠方式拼接长视频。</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"495.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">流式输出时按块解码与返回，显存峰值由单块潜变量与注意力工作集决定。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-1\">一 · 在线服务现场：一次提示词请求如何压垮旧栈</h3>\n<p>设想一个短视频创作平台的在线服务：用户在网页输入一句提示词，期望在数秒内拿到一段数秒长、可循环播放的短视频，并且平台按并发请求数计费。请求进入调度器后，旧栈的典型做法是“一个端到端的高分辨率视频扩散模型”——文本编码器给出条件嵌入，扩散网络直接在目标像素分辨率或接近目标分辨率的潜空间上做几十步去噪，每步一次三维时空注意力前向，最后三维 VAE 一次性解码整段视频。这条路径在离线批处理里尚可忍受，一旦放到在线服务就暴露出三个耦合在一起的代价：延迟由“步数 × 单步时空注意力时延”决定，吞吐由“显存能塞下多少个并发潜变量”决定，而显存峰值由“最高分辨率潜变量 + 注意力工作集 + 解码器激活”三者叠加决定。三者互相牵制：想降延迟就减步数，画质塌；想提吞吐就加批，显存爆；想省显存就降分辨率，细节丢。工程上非改不可的不是某个算子，而是这条“单模型直出高分辨率”的推理拓扑本身。</p>\n<p>把代价写成可核算的形式。设扩散步数为 <span class=\"formula\">$$T$$</span>，潜变量在时间、空间上的元素数为 <span class=\"formula\">$$N$$</span>，单步时空注意力的计算量近似随 <span class=\"formula\">$$N^2$$</span> 增长（全局注意力）或随 <span class=\"formula\">$$N \\cdot w$$</span> 增长（窗口注意力，<span class=\"formula\">$$w$$</span> 为窗口元素数），则端到端时延的量级为：</p>\n<div class=\"formula\">$$\\tau \\approx T \\cdot \\big(\\tau_{\\text{attn}}(N) + \\tau_{\\text{mlp}}(N)\\big) + \\tau_{\\text{VAE}}(N_{\\text{pixel}})$$</div>\n<p>其中 <span class=\"formula\">$$\\tau_{\\text{VAE}}$$</span> 是三维解码的时延，它随像素体量线性增长且受显存带宽约束远重于受算力约束。这个式子说明一件事：在旧栈里，<span class=\"formula\">$$N$$</span> 被目标分辨率钉死，<span class=\"formula\">$$T$$</span> 被画质钉死，两个乘数都无法单独压缩，唯一能动的只有“把 <span class=\"formula\">$$N$$</span> 从高分辨率降到低分辨率”——而这正是级联路径的切入点。具体例子：一个 16 帧、目标 1024 级短边的请求，若直接在目标潜空间跑满步数，单请求就占住一份可观的显存工作集，调度器只能把并发压到个位数，尾延迟随排队迅速抬升；而如果把基础去噪放到低分辨率潜空间、把放大交给后续模块，同样的显存预算能容纳更多在途请求。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-2\">二 · 旧栈的第二个死结：没有成对文本视频数据，条件注入无处落脚</h3>\n<p>旧栈的痛点不止在算力。文本到视频的监督信号传统上依赖大规模成对“文本—视频”数据，而这类数据的获取与清洗成本极高，标注粒度也难以对齐到帧级运动。缺少这种数据时，工程上常见的退路是“文本—图像”模型加时间维微调，但直接把图像模型的时间维拉开会带来两个推理侧后果：其一，文本条件只在图像分支上被训练过，视频分支的条件嵌入与运动语义脱节，采样时容易出现“画面对、运动错”的失败；其二，为了让时间维收敛，往往要给整段视频做全局时空注意力，进一步把 <span class=\"formula\">$$N$$</span> 推高，回到第一节的显存死结。于是旧栈陷入循环：数据不够→靠全局注意力硬拟合时间一致性→显存与时延恶化→只能减分辨率或减步数→画质与一致性双降。</p>\n<p>论文的破局点在于把“条件注入”和“时间维扩展”拆成两件事分别解决：文本条件通过图像—文本对注入到图像先验里，时间维则在无标注视频上以时空超分与帧插值式模块扩展。对推理栈而言，这不是训练技巧，而是拓扑改变——它允许基础生成器停在低分辨率潜空间，把高分辨率的负担交给一个只做放大的模块，把帧率的负担交给一个只做插值的模块。代价被分摊到三个可独立批处理、独立调优的阶段，而不是压在一个模型上。这里的工程判断是：级联各阶段的显存峰值不再由同一份最高分辨率潜变量决定，而是由各自阶段的输入分辨率决定，调度器因此获得了“按阶段排队、按阶段扩批”的自由度。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-3\">三 · 级联路径的推理形态与每段的代价归属</h3>\n<p>论文给出的推理路径可写成一条复合映射：</p>\n<div class=\"formula\">$$\\hat{x}_{0}=\\mathcal{D}\\big(\\mathcal{I}(\\mathcal{S}(\\epsilon_\\theta(z_T,c)))\\big),\\quad z_{t-1}=\\frac{1}{\\sqrt{\\alpha_t}}\\Big(z_t-\\frac{\\beta_t}{\\sqrt{1-\\bar{\\alpha}_t}}\\epsilon_\\theta(z_t,t,c)\\Big)+\\sigma_t\\xi$$</div>\n<p>读法要按阶段拆：<span class=\"formula\">$$\\epsilon_\\theta$$</span> 是基础视频生成器，在低分辨率潜空间从 <span class=\"formula\">$$z_T$$</span> 出发按采样公式迭代，<span class=\"formula\">$$c$$</span> 是文本编码器给出的条件嵌入；<span class=\"formula\">$$\\mathcal{S}$$</span> 是时空超分，在空间与时间两维同时放大并复用低分辨率条件；<span class=\"formula\">$$\\mathcal{I}$$</span> 是帧插值，在相邻帧间补帧提升帧率；<span class=\"formula\">$$\\mathcal{D}$$</span> 是三维 VAE 解码，把潜变量还原为像素。每段的代价归属不同：基础阶段的时延由步数与低分辨率潜变量的注意力工作集主导，显存峰值由该潜变量与注意力中间张量决定；超分阶段的代价集中在一次前向的空间放大，显存由放大后的潜变量决定，但它只跑一次而非 <span class=\"formula\">$$T$$</span> 次；插值阶段代价最轻，却直接决定运动连续性；解码阶段是带宽密集型，吞吐受显存读写带宽约束而非算力。具体例子：同一请求若把基础阶段的分辨率减半，注意力工作集按平方级缩小，而超分模块只增加一次前向的开销——总时延的乘数结构从 <span class=\"formula\">$$T \\times \\text{高分辨率}$$</span> 变成 <span class=\"formula\">$$T \\times \\text{低分辨率} + \\text{一次放大}$$</span>，这是级联路径最直接的收益来源。</p>\n<p>条件嵌入的复用也是推理侧的一处节省：文本编码器只跑一次，输出供基础、超分、插值各级模块共享，避免每级重复编码。这在批处理下尤其重要，因为文本编码的批处理效率与视觉分支不同，混在同一批里会拉低整体利用率。工程上应把文本编码单独成阶段、单独定批，再把嵌入广播给下游。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-4\">四 · 长视频与流式：分块重叠把显存峰值钉在单块上</h3>\n<p>短视频之外，长视频请求把旧栈的显存问题放大到不可解：整段视频的潜变量与注意力工作集随帧数线性甚至超线性增长，一次性解码整段视频的峰值显存随长度无界。论文的应对是分块与重叠拼接——把长视频切成块，块间保留重叠帧以抑制接缝，流式场景下逐块解码并返回。推理侧的意义在于：显存峰值由单块潜变量与注意力工作集决定，而与总长度解耦；代价则转移到块间一致性上，重叠帧不足会出现接缝与帧间跳变，重叠过多则浪费算力与带宽。</p>\n<p>设块长为 <span class=\"formula\">$$L$$</span>、重叠为 <span class=\"formula\">$$o$$</span>，则总计算量相对无重叠的放大系数为 <span class=\"formula\">$$L/(L-o)$$</span>，而接缝风险随 <span class=\"formula\">$$o$$</span> 减小而上升。这是一个显存—一致性—吞吐的三方权衡：<span class=\"formula\">$$o$$</span> 取大，接缝少但每块有效产出低、解码带宽浪费；<span class=\"formula\">$$o$$</span> 取小，吞吐高但需要额外的跨块条件传递来维持运动连续。流式返回还引入 SLO 结构变化：首块时延决定首帧可见时间，后续块的解码带宽决定播放是否卡顿，二者要分开设指标，不能用一个端到端平均值掩盖。具体例子：一个长视频请求在流式模式下，调度器按块粒度占显存、按块粒度释放，峰值不再随总时长抬升；但如果块边界正好落在快速运动段，重叠不足会直接表现为可见跳变，这类失败只能靠块间接缝一致性与帧间运动一致性的监控项捕获，而不是靠端到端时延发现。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-5\">五 · 为什么非改不可：旧栈的三个不可调和项</h3>\n<p>把痛点收敛成三条工程判断。第一，延迟结构不可压缩：旧栈的时延是“步数 × 高分辨率单步”的乘积，两个因子都被画质目标锁死，减任何一个都直接掉画质；级联路径把高分辨率从乘数里拿出来，变成加数，这是拓扑级的改善而非调参。第二，显存峰值不可预测：旧栈的峰值由整段视频的最高分辨率潜变量决定，随请求长度漂移，调度器无法给出稳定的并发上限；分块与级联把峰值钉在单块、单阶段上，容量规划才有依据。第三，一致性不可归因：旧栈把条件、运动、细节混在一个模型里，失败时无法判断是条件没注入、时间维没收敛还是解码器失真；级联把三者分到不同阶段，监控项可以分别挂在超分、插值与解码上。这三条合起来就是“非改不可”的理由——不是因为旧栈跑不动，而是因为它无法在在线服务里给出可核算、可归因、可扩批的推理形态。</p>\n<p>需要诚实标注的是，材料未给出具体步数、分辨率、硬件档位与精度方案，因此上述代价只能落到机制层面：多步时空注意力与三维解码是主要开销，分块接缝与帧间一致性是主要失败模式。级联各阶段可独立批处理，但跨阶段流水线要管理潜变量传输，传输本身的带宽开销在分块流式下不可忽略。若后续在三维解码与注意力上套用低精度量化，必须同时监控帧间一致性与块间接缝，因为解码精度的损失会以运动不连续的形式暴露，而不是以单帧画质的形式暴露。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-6\">六 · 级联栈的边界：当“先低分辨率再放大”撞上在线服务的显存墙</h3>\n<p>设想一个在线短视频生成服务：用户提交一段提示词，期望在数秒内拿到数秒长、可播放的片段，且并发请求按分钟级波动。在这篇论文的推理栈里，一次请求要穿过四级级联：文本编码器给出条件嵌入，基础生成器在低分辨率潜空间按扩散采样公式迭代去噪，时空超分模块在空间与时间两维放大，帧插值模块补帧，最后由三维 VAE 解码为像素。这条路径的工程意义在于把“高分辨率视频扩散”这个不可承受的单项拆成若干可分别优化的阶段；但它的代价并没有消失，只是被搬到了阶段边界上——显存峰值由最高分辨率潜变量与注意力工作集决定，而吞吐由三维解码的带宽与时空注意力的计算共同卡住。</p>\n<p>旧方案的主流做法是直接在目标分辨率上做视频扩散：单模型、单次采样循环，潜变量尺寸与注意力工作集随分辨率平方增长，长视频还要在时间维上整体展开。其失效条件很明确：显存峰值随潜变量分辨率与帧数同时上升，注意力工作集无法通过简单切批缓解；解码阶段一次性还原全部像素，带宽开销集中爆发。级联栈把这个问题改写为分段预算问题：基础生成器在低分辨率潜空间迭代，每步只需一次时空注意力前向，显存由低分辨率潜变量主导；超分与插值各自承担一段放大，解码按块进行。代价是跨阶段潜变量传输与流水线管理——各阶段可独立批处理，但阶段间的分辨率跃迁决定了显存峰值的落点，把某一级调得过激会立刻顶到下一级的墙上。</p>\n<div class=\"formula\">$$\\hat{x}_{0}=\\mathcal{D}\\big(\\mathcal{I}(\\mathcal{S}(\\epsilon_\\theta(z_T,c)))\\big),\\quad z_{t-1}=\\frac{1}{\\sqrt{\\alpha_t}}\\Big(z_t-\\frac{\\beta_t}{\\sqrt{1-\\bar{\\alpha}_t}}\\epsilon_\\theta(z_t,t,c)\\Big)+\\sigma_t\\xi$$</div>\n<p>把上式拆开看系统代价：采样循环的每一步都是一次完整的时空注意力前向，步数与潜变量分辨率共同决定基础阶段的时延；超分与插值阶段复用低分辨率条件，避免重复采样，但它们引入新的失败模式——长视频按块切分并保留重叠帧以抑制接缝，块大小与重叠比例必须与显存上限联动，重叠不足直接表现为接缝与帧间跳变，重叠过多则吞掉吞吐。流式场景下逐块解码返回，端到端 SLO 由解码带宽与注意力计算共同约束，而非由某一级单独决定。材料未给出具体步数、分辨率与硬件档位，因此这里只能落到机制判断：级联栈的边界不在单级性能，而在跨阶段潜变量分辨率与显存峰值的耦合；把各级当作独立模型分别调优，是这个栈最典型的工程误判。</p>\n<table class=\"mini\"><thead><tr><th>阶段</th><th>主导资源</th><th>失效条件</th></tr></thead><tbody><tr><td>低分辨率扩散采样</td><td>时空注意力计算、潜变量显存</td><td>步数偏多时端到端时延线性上升</td></tr><tr><td>时空超分</td><td>放大后的潜变量显存与带宽</td><td>放大倍率顶到显存上限，块重叠被迫压缩</td></tr><tr><td>帧插值</td><td>帧间一致性评估开销</td><td>运动剧烈处插值引入不一致，需与超分联合评估</td></tr><tr><td>三维 VAE 解码</td><td>解码带宽</td><td>逐块解码吞吐受限，流式返回节奏被带宽卡住</td></tr></tbody></table>\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-7\">七 · 请求形态的测量口径：把“一句提示词”拆成可计量的字段</h3>\n<p>文本到视频的请求在推理系统里从来不是“一句话”这么简单，它至少由四个可独立测量的字段构成：提示词 token 数、目标帧数、目标分辨率、是否要求流式返回。Make-A-Video 的级联路径（低分辨率扩散采样 → 时空超分 → 帧插值 → 三维 VAE 解码）意味着这四个字段分别落在不同阶段的开销上：token 数只影响文本编码器与条件嵌入的构造，帧数影响时间维注意力与解码的块数，分辨率影响潜变量尺寸与超分模块的工作集，流式标志决定解码是按块返回还是一次性拼完。可核查的测量口径应当是：在请求入口处记录 <code>(len(prompt_tokens), T_frames, H×W, streaming)</code> 四元组，并按四元组分桶统计到达率与驻留时间，而不是只报一个平均 QPS。提示词长度分布材料未给出，但文本编码器有最大长度，超长提示词必须截断——截断本身是一个可观测事件，应单独计数，因为它意味着条件信息丢失，且截断后的请求与未截断请求在语义上不可比，混在同一桶里会污染延迟统计。</p>\n<p>并发与批大小的口径同样要落到阶段上。级联各阶段可以独立批处理，但它们的批维度并不对齐：基础生成器按潜变量序列批，超分模块按块批，解码按帧块批。因此“批大小”必须声明是哪个阶段的批，否则数字无法比较。一个可用的记账方式是定义端到端有效批 <code>B_eff</code> 与各阶段批 <code>B_i</code> 的关系：若阶段 i 对每个请求产生 <code>n_i</code> 个独立工作项（例如解码阶段的块数），则该阶段实际并发为 <code>B_i = B_eff · n_i</code>。这直接决定显存峰值：显存峰值由最高分辨率潜变量与注意力工作集决定，而工作集随 <code>B_i</code> 线性增长。工程判断是：不要用入口并发数去估算显存，要用“入口并发 × 该阶段每请求工作项数 × 单工作项工作集”去估算，三者缺一不可。</p>\n<div class=\"formula\">$$M_{\\text{peak}} \\approx B_{\\text{eff}}\\cdot n_i \\cdot \\big( S_{\\text{latent}}(H_i,W_i,T_i) + S_{\\text{attn}}(H_i,W_i,T_i) \\big) + M_{\\text{static}}$$</div>\n<p>其中 <code>S_latent</code> 是潜变量张量字节数，<code>S_attn</code> 是时空注意力工作集，<code>M_static</code> 是权重与文本编码器常驻部分。这个式子不是精确模型，而是容量规划时必须显式写出的三个乘子——漏掉 <code>n_i</code> 是最常见的低估来源。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-8\">八 · 长尾从哪里来：块数、重叠与流式的耦合</h3>\n<p>视频请求的延迟长尾不像文本请求那样主要来自输出长度，而主要来自“块数 × 每块代价”的乘积效应。长视频按块切分并保留重叠帧，设总帧数 <code>T</code>、块长 <code>L</code>、重叠 <code>O</code>，则块数为 <code>N_blk = ceil((T − O) / (L − O))</code>。重叠比例 <code>O/L</code> 是一个纯粹的系统参数：它越大，接缝越不明显，但块数越多、重复计算越多，端到端时延近似按 <code>N_blk</code> 线性上升。于是同一套模型下，一个 2 倍帧数的请求可能产生远大于 2 倍的时延——这是长尾的结构性来源，而不是偶发的调度抖动。</p>\n<div class=\"formula\">$$\\text{Latency} \\;\\approx\\; N_{\\text{blk}}\\cdot\\big(t_{\\text{sample}} + t_{\\text{decode}}^{\\text{blk}}\\big) + t_{\\text{interp}},\\quad N_{\\text{blk}}=\\left\\lceil \\frac{T-O}{L-O}\\right\\rceil$$</div>\n<p>流式返回把这条曲线切成阶梯：第 k 块解码完成即可返回，首块时延（TTFB）只与单块采样加单块解码有关，而总时延仍随 <code>N_blk</code> 增长。SLO 因此必须分两个指标写：首块时延与全部块完成时延，二者不可互相替代。若只对端到端时延设 SLO，流式路径的优势被掩盖；若只对 TTFB 设 SLO，长请求会静默拖垮队列。可核查的口径是：对每个请求记录块级时间戳序列，统计 TTFB 的 p50/p99 与“块间间隔”的 p99——块间间隔的抖动直接反映解码带宽竞争与注意力计算的排队情况，是比端到端时延更灵敏的拥塞信号。</p>\n<p>具体例子：一个请求要求较高帧率，帧插值模块在相邻帧间生成中间帧。插值发生在所有块之后还是逐块进行，决定了显存与延迟的形态——逐块插值只需保留相邻两块的重叠帧，显存峰值不随总帧数增长；全局插值则需保留全部帧，显存随 <code>T</code> 线性上升。材料未给出实现选择，但容量规划必须假定其一并写明，否则 <code>M_peak</code> 的估算没有意义。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-9\">九 · 负载如何塑造方案：批处理边界与条件复用</h3>\n<p>负载形态反过来约束方案设计，最直接的一条是：级联各阶段的批处理边界不由框架决定，而由显存峰值所在的阶段决定。由于显存峰值由最高分辨率潜变量与注意力工作集主导，超分与解码阶段天然是批大小的瓶颈，而低分辨率扩散阶段反而可以吃更大的批。于是合理的方案是“非对称批”：扩散阶段大批、超分与解码阶段小批，中间用潜变量队列解耦。代价是跨阶段流水线需管理潜变量传输——潜变量在设备间或进程间搬运的带宽开销，会部分抵消大批带来的吞吐收益。这是一个必须实测的权衡点，材料未给出并行与通信细节，因此只能落到机制判断：潜变量传输量与 <code>B_eff × S_latent</code> 成正比，若传输带宽不足以在扩散阶段产出的速率下消费，队列会反向阻塞上游。</p>\n<p>第二条是条件复用。文本条件通过图像文本对注入，推理时文本编码器输出条件嵌入供各级模块复用。这意味着同一提示词的多次请求（例如同一提示词生成多个候选、或调参重试）可以共享一次文本编码，把文本编码从每请求一次降为每提示词一次。可核查的口径是“条件嵌入缓存命中率”：命中率越高，文本编码器在关键路径上的占比越低。但缓存键必须包含截断后的 token 序列与编码器版本，否则跨版本复用会引入不可见的条件漂移。</p>\n<p>第三条是 SLO 与批大小的耦合。连续批处理在扩散采样这种多步迭代里并不是免费的：每一步都要一次时空注意力前向，新请求若在步间插入，会改变该步的批组成，使不同请求共享同一步的注意力计算，但也让先到请求的完成时间被后到请求拉长。对视频而言，由于每步代价高、步数多，插入的收益与抖动都被放大。工程判断是：把“步间插入”与“块间插入”分开计量——块间插入只影响后续块，抖动局部；步间插入影响当前请求的剩余全部步数，抖动全局。SLO 若对 p99 敏感，应优先允许块间插入。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-10\">十 · 方案反过来限制负载：准入、截断与降级</h3>\n<p>方案对负载的反向限制体现在三个可配置的闸门上，每一个都应被显式记录为拒绝或降级事件，而不是静默发生。第一是提示词截断：文本编码器最大长度是硬约束，超长提示词被截断后条件信息丢失，生成结果与请求意图不符，但系统仍会计为成功。可核查口径是截断率与截断 token 数的分布。第二是帧数与分辨率的上限：<code>N_blk</code> 与潜变量尺寸共同决定显存峰值，超过上限的请求必须被拒绝或降级到更低分辨率/更短帧数。降级不是免费的——降级后的输出与请求规格不符，应在响应中标注，否则下游无法区分“按规格完成”与“降级完成”。第三是流式与非流式的分流：流式请求占用解码带宽的时间更长（逐块返回意味着解码与传输交错），在高并发下会挤压非流式请求的批空间。准入控制应按流式标志分池，而不是混在一个队列里按 FIFO 调度。</p>\n<p>具体例子：当解码带宽成为瓶颈时，降低分辨率比降低帧数更有效——解码开销与像素数成正比，而帧数只线性增加块数。反过来，当注意力计算成为瓶颈时，降低帧数（缩短时间维）比降低分辨率更有效，因为时空注意力的工作集随 <code>T</code> 增长。这两个方向的取舍取决于当前瓶颈在哪，因此监控必须同时给出“解码带宽利用率”与“注意力计算利用率”两个独立指标，而不是一个笼统的 GPU 利用率。材料未给出量化方案，若引入 NVFP4/FP8 量化三维解码与注意力，需同时监控帧间一致性与块间接缝——低精度可能放大帧间不一致，而这类失败不会体现在吞吐指标上。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-11\">十一 · 可核查的监控面板：把机制翻译成指标</h3>\n<p>把上述机制落成一张可核查的面板，至少包含以下条目，每条都对应一个具体机制而非笼统健康度。<table class=\"mini\"><thead><tr><th>指标</th><th>对应机制</th><th>用途</th></tr></thead><tbody><tr><td>提示词 token 数分桶与截断率</td><td>文本编码器最大长度</td><td>识别条件丢失，分离截断请求的延迟统计</td></tr><tr><td>每请求块数 <code>N_blk</code> 分布</td><td>分块与重叠比例</td><td>解释端到端时延长尾的结构性来源</td></tr><tr><td>TTFB p50/p99 与块间间隔 p99</td><td>流式逐块解码</td><td>区分首块时延与拥塞抖动</td></tr><tr><td>各阶段批大小 <code>B_i</code> 与显存峰值</td><td>非对称批与潜变量工作集</td><td>验证 <code>M_peak</code> 估算，定位瓶颈阶段</td></tr><tr><td>条件嵌入缓存命中率</td><td>文本条件跨阶段复用</td><td>衡量文本编码在关键路径的占比</td></tr><tr><td>解码带宽利用率与注意力利用率（分开）</td><td>三维解码与时空注意力</td><td>决定降分辨率还是降帧数的降级方向</td></tr><tr><td>块间接缝一致性与帧间运动一致性</td><td>重叠拼接与帧插值</td><td>捕捉低精度量化引入的隐性质量退化</td></tr></tbody></table></p>\n<p>这张表的关键在于每一行都能被独立采样并归因：块数分布解释长尾，块间间隔解释抖动，两个利用率指标解释降级方向，一致性指标解释质量退化。缺少任何一行，容量规划就只能靠端到端时延一个数字反推，而端到端时延是所有这些机制叠加后的结果，无法反解。工程判断是：先固定测量口径（四元组分桶、阶段批声明、块级时间戳），再谈 SLO 数值；口径不统一的吞吐与延迟数字在级联式视频生成里没有比较意义。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-12\">十二 · 级联栈的负载塑形：谁在决定批大小与块边界</h3>\n<p>Make-A-Video 的推理负载不是一条“提示词进、视频出”的均质流，而是被级联栈的四个阶段切成形态迥异的四段：文本编码、低分辨率潜空间多步去噪、时空超分与帧插值、三维 VAE 解码。真正塑造方案的是第三、四段的显存峰值——它由最高分辨率潜变量与注意力工作集共同决定，而非由基础生成器的低分辨率采样决定。这意味着批大小不能按最便宜的那一段来定，而必须按最贵的那一段反推：设单块潜变量显存为 $M_{\\text{lat}}$、注意力工作集为 $M_{\\text{att}}$、解码临时缓冲为 $M_{\\text{dec}}$，则单请求显存下界为 $M_{\\text{req}} \\ge M_{\\text{lat}} + M_{\\text{att}} + M_{\\text{dec}}$，可容纳并发 $B \\le \\lfloor M_{\\text{avail}} / M_{\\text{req}} \\rfloor$。工程后果是：基础生成器那一段本可吃下更大批以摊薄权重读取带宽，却被超分/解码段的显存天花板锁死，形成“前段饿、后段撑”的流水线气泡。</p>\n<p>长视频把这一矛盾推到极致。分块与重叠拼接是唯一可行的显存控制手段，块大小与重叠比例必须与显存上限联动：重叠帧越多，接缝抑制越好，但每块的有效产出帧数下降，端到端时延按 $T_{\\text{e2e}} \\approx \\lceil N_f / (F_{\\text{blk}} - F_{\\text{ov}}) \\rceil \\cdot (t_{\\text{samp}} + t_{\\text{dec}})$ 增长，其中 $F_{\\text{blk}}$ 为块帧数、$F_{\\text{ov}}$ 为重叠帧数。流式场景下逐块解码返回，SLO 被解码带宽与注意力计算共同约束——首块时延决定首帧可见时间，后续块时延决定播放是否卡顿，两者是不同口径的 SLO，不能合并成一个平均值汇报。可核查的测量口径应至少包含：单块解码耗时分布（P50/P99）、块间重叠区像素差、相邻块边界帧的运动矢量跳变、以及显存峰值随块大小的采样曲线。</p>\n<p>级联各阶段可独立批处理，但跨阶段流水线需管理潜变量传输：文本编码器输出的条件嵌入应被各级模块复用，避免重复编码；而基础生成器产出的粗潜变量在送入超分前需按块切分并保留重叠，这一拷贝在显存带宽上是实打实的代价。失效条件很明确：把四个阶段当作独立模型分别调优批大小与并行切分，忽略跨阶段潜变量分辨率与显存峰值的耦合，结果是某一段成为隐性瓶颈而其余段空转。另一个失效点是重叠不足——接缝与帧间跳变不会在吞吐指标上暴露，只会以一致性监控缺失的形式潜伏。</p>\n<table class=\"mini\"><thead><tr><th>测量项</th><th>口径</th><th>受哪个阶段主导</th></tr></thead><tbody><tr><td>首块时延</td><td>请求到首块像素返回</td><td>基础采样步数＋单块解码</td></tr><tr><td>稳态块间隔</td><td>相邻块返回时间差 P99</td><td>三维解码带宽</td></tr><tr><td>显存峰值</td><td>按块大小扫描的采样曲线</td><td>潜变量＋注意力工作集</td></tr><tr><td>接缝一致性</td><td>重叠区像素差与运动跳变</td><td>重叠比例与超分/插值耦合</td></tr></tbody></table>\n<p>方案反过来限制负载：级联路径决定了请求必须以“短视频优先、长视频分块”的形态进入系统，提示词按文本编码器最大长度截断，超长提示不获得额外条件带宽；批大小被最高分辨率段锁死后，调度器只能用连续批处理在段内填补空隙，而无法跨段合并。若量化三维解码与注意力，需同步监控帧间一致性与块间接缝——低精度在解码段的误差会被分块拼接放大为可见跳变，这是精度方案与负载形态耦合的典型失效面。</p>\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-13\">十三 · 从级联路径反推 kernel 热点</h3>\n<p>Make-A-Video 的推理图是四级级联：文本编码器 → 低分辨率潜空间多步去噪 → 时空超分 → 帧插值 → 三维 VAE 解码。要在 Blackwell 上把它做快，第一步不是选精度，而是把这条路径拆成可映射到 SM 的 kernel 清单。基础生成器每步去噪的核心是时空注意力：给定潜变量 <span>z_t ∈ R^{F×H×W×C}</span>（F 帧、H×W 空间、C 通道），注意力在展平后的 <span>N = F·H·W</span> 个 token 上做 QK^T 与 softmax·V，复杂度为 <span>O(N²d)</span>；当 F 增大时 N 线性增长、注意力代价平方增长，这是级联里第一个真正的算力热点。第二个热点是三维 VAE 解码器：它把潜变量还原为像素，卷积核在时间维上滑动，访存模式是典型的带宽受限——每输出一个像素块要读入邻域帧的激活，算术强度低，落在 HBM 带宽而非 Tensor Core 上。第三个是超分模块，空间上采样后 token 数按倍率平方增长，若直接在全分辨率上重跑注意力，代价会盖过基础生成器本身。</p>\n<p>因此 kernel 选型要按“算力受限 / 带宽受限”两类分开处理：注意力与线性层走 Tensor Core 路径（GEMM 形态的 QKV 投影、MLP、以及 attention 的 QK^T 与 PV），三维卷积与上采样走访存优化路径（合并时间维、channel-last 布局、尽量让一次读入服务多个输出）。把这两类混在一个融合 kernel 里通常得不偿失，因为 Tensor Core 的 tile 形状与卷积的邻域重用模式不兼容。</p>\n<p>代价上要盯住一个量：单步去噪的显存工作集。它由 <span>z_t</span>、注意力 QKV 中间量、以及 softmax 归一化缓冲共同决定，量级随 <span>N·d</span> 走。级联后段（超分、解码）的峰值往往不在同一时刻出现，这给分阶段流水线留出了显存复用的窗口——但前提是跨阶段的潜变量传输被显式管理，而不是让框架默认保留所有中间张量。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-14\">十四 · 精度阶梯：FP16 / BF16 / FP8 / NVFP4 各自落在哪一级</h3>\n<p>Blackwell 的第五代 Tensor Core 把低精度矩阵乘的吞吐阶梯拉开：FP16/BF16 是基线，FP8（E4M3/E5M2）在相同 tile 下吞吐翻倍，NVFP4（E2M1 加块级缩放）再翻一倍。但视频扩散的误差敏感度在级联各段并不均匀，不能一刀切。</p>\n<p>文本编码器与条件嵌入：输出要参与每一级模块的 cross-attention，数值扰动会被多步采样放大，保持 BF16 是稳妥选择；其计算量占比小，降精度收益可忽略。</p>\n<p>基础生成器：这是算力主战场，QKV 投影与 MLP 是 GEMM 密集型，适合 FP8。注意力里的 QK^T 对精度更敏感——softmax 前的 logits 若量化过粗，注意力分布会偏移，表现为运动轨迹漂移；工程上常见做法是 QK^T 用 FP8 而 PV 与 softmax 归一化保留更高精度，或对 logits 做块级缩放。NVFP4 在这一级要谨慎：多步迭代会累积误差，且视频的时空一致性对微小扰动比单帧图像更敏感。</p>\n<p>时空超分与帧插值：这两级是“放大”操作，误差会被上采样核在空间与时间上扩散。超分的输入是基础生成器的粗潜变量，若粗潜变量本身已带 FP8 误差，再叠加超分的低精度，接缝与帧间跳变会同时恶化。建议超分主体用 FP8、输出投影回 BF16；帧插值因为要在相邻帧间插值出中间运动，对时间维的数值连续性要求最高，保守留在 BF16。</p>\n<p>三维 VAE 解码：带宽受限，降精度的主要收益是减少激活读写字节数而非提升算力。FP8 激活可以把解码阶段的 HBM 流量压下来，但解码输出直接成为像素，量化噪声会以块状伪影形式出现在画面上，且长视频分块拼接时不同块的量化误差不一致，接缝会更明显。可行路径是解码主体 FP8、最后的重建层回 BF16。</p>\n<table class=\"mini\"><thead><tr><th>级联阶段</th><th>受限类型</th><th>建议精度</th><th>主要风险</th></tr></thead><tbody><tr><td>文本编码器</td><td>算力次要</td><td>BF16</td><td>条件漂移被多步放大</td></tr><tr><td>基础去噪（GEMM）</td><td>算力受限</td><td>FP8</td><td>多步误差累积</td></tr><tr><td>注意力 QK^T</td><td>算力受限</td><td>FP8 + 块缩放</td><td>注意力分布偏移</td></tr><tr><td>时空超分</td><td>算力受限</td><td>FP8，输出 BF16</td><td>误差随上采样扩散</td></tr><tr><td>帧插值</td><td>算力中等</td><td>BF16</td><td>时间维不连续</td></tr><tr><td>三维 VAE 解码</td><td>带宽受限</td><td>FP8 激活，末层 BF16</td><td>块状伪影与接缝</td></tr></tbody></table>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-15\">十五 · 累加精度与误差传播的公式拆解</h3>\n<p>低精度 GEMM 的误差不只来自输入量化，还来自累加。Blackwell Tensor Core 在 FP8 与 NVFP4 路径上以更高位宽累加（FP8 路径通常 FP32 累加，NVFP4 路径亦有块级缩放与较宽累加），但累加器宽度与归约顺序仍决定最终误差量级。对一次 <span>K</span> 维点积，量化误差上界可写成：</p>\n<div class=\"formula\">$$\\big|\\hat{y}-y\\big|\\ \\le\\ \\sum_{k=1}^{K}\\big|\\hat{a}_k\\hat{b}_k-a_kb_k\\big|\\ \\approx\\ \\sum_{k=1}^{K}\\big(|a_kb_k|(\\epsilon_a+\\epsilon_b)\\big)\\ +\\ \\epsilon_{\\text{acc}}\\sum_{k=1}^{K}|a_kb_k|$$</div>\n<p>逐项解释：第一项是输入量化误差，<span>ε_a、ε_b</span> 分别是 A、B 的相对量化步长（FP8 E4M3 约 2^-3 量级尾数、NVFP4 E2M1 只有 1 位尾数加块缩放，故 <span>ε</span> 显著更大）；第二项是累加误差，<span>ε_acc</span> 由累加器位宽与归约树深度决定。关键结论是误差随 <span>K</span> 与激活幅值的和增长，因此对幅值大的层（如残差前的投影）更敏感；块级缩放（NVFP4 的 per-block scale）正是把 <span>|a_kb_k|</span> 的动态范围压进尾数可表示区间，从而压小第一项。</p>\n<p>把这个界放进扩散采样公式看传播：</p>\n<div class=\"formula\">$$z_{t-1}=\\frac{1}{\\sqrt{\\alpha_t}}\\Big(z_t-\\frac{\\beta_t}{\\sqrt{1-\\bar{\\alpha}_t}}\\,\\hat{\\epsilon}_\\theta(z_t,t,c)\\Big)+\\sigma_t\\xi,\\qquad \\hat{\\epsilon}_\\theta=\\epsilon_\\theta+\\delta_t$$</div>\n<p>其中 <span>δ_t</span> 是第 t 步去噪网络输出的数值误差。由于 <span>β_t/√(1-ᾱ_t)</span> 在采样早期较大，早期步的 <span>δ_t</span> 被放大得更厉害；而早期步恰恰决定视频的整体结构与运动走向。这解释了为什么“基础生成器全 FP8”在图像上可行、在视频上却容易出现运动漂移：误差在时间维上被后续帧插值与超分进一步放大。工程判断是：早期采样步（高噪声段）保留 BF16 或至少 FP8 高精度档，后期步（低噪声段）可降到 NVFP4，因为此时 <span>β_t/√(1-ᾱ_t)</span> 小、误差增益低。</p>\n<p>代价侧：FP8 相对 BF16 在同一 tile 下吞吐翻倍，直接缩短单步去噪时延；NVFP4 再翻倍但需要块缩放元数据，增加寄存器与共享内存压力，且缩放因子的计算本身是额外指令开销。对带宽受限的三维解码，FP8 激活把每字节承载的元素数翻倍，等效带宽利用率提升，这是解码阶段最实在的收益。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-16\">十六 · Blackwell 特性如何落到这些 kernel 上</h3>\n<p>tcgen05 是 Blackwell 的第五代 Tensor Core 指令族，配合 TMEM（Tensor Memory）把矩阵乘的累加器从寄存器文件搬到专用片上存储。对视频扩散的意义在于：注意力与 MLP 的 GEMM tile 可以更大，累加器不再挤占寄存器，寄存器压力释放后可以同时驻留更多 QKV 分块，减少 shared memory 与 register 之间的搬运。TMEM 的容量约束决定了单 CTA 能容纳的累加器规模，进而决定 tile 形状选择——这是 kernel 调优的第一约束，而不是算力峰值。</p>\n<p>2-SM MMA（两 SM 协同的矩阵乘）让一个 MMA 操作跨两个 SM 共享操作数，等效于把 tile 的 M 或 N 维加倍而不增加单 SM 的存储压力。对时空注意力尤其有用：当 <span>N = F·H·W</span> 很大时，QK^T 的 tile 天然偏大，2-SM 形态可以在不切碎 K 维的情况下维持高 Tensor Core 利用率。代价是跨 SM 的同步与数据分发开销，若 tile 太小则协调成本盖过收益——所以它适合基础生成器与超分的大 GEMM，不适合解码阶段的小卷积。</p>\n<p>第五代 Tensor Core 的低精度路径还带来一个结构性变化：FP8 与 NVFP4 的吞吐阶梯使“混合精度流水线”成为默认设计而非可选优化。具体做法是把级联各段标注精度档，在阶段边界做显式的精度转换 kernel（BF16↔FP8），而不是让框架隐式转换——隐式转换会插入未融合的 cast，破坏流水线并增加带宽。转换点的位置应选在张量尺寸最小的边界（如条件嵌入、粗潜变量），把转换开销摊薄。</p>\n<p>显存与带宽代价要一起算：TMEM 与更大 tile 提升算力利用率，但潜变量与注意力工作集仍占 HBM；分块长视频时，块间重叠帧的潜变量需要保留，重叠比例直接乘在显存峰值上。若重叠比例取 r，则有效显存需求约按 <span>(1+r)</span> 倍单块工作集增长，这是分块策略与显存上限联动的量化依据。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-17\">十七 · 一个可执行的精度配置与监控闭环</h3>\n<p>把上述判断落成配置：文本编码器 BF16；基础去噪前若干高噪声步 BF16、其余步 FP8（QKV 与 MLP），注意力 QK^T 用 FP8 加块级缩放、PV 与 softmax 归一化 BF16；时空超分 FP8 主体、输出投影 BF16；帧插值 BF16；三维 VAE 解码 FP8 激活、重建末层 BF16。伪代码思路如下：</p>\n<ul>\n<li>按采样步索引 t 查精度档表：<span>t &gt; t_hi</span> 走 BF16 分支，否则走 FP8 分支；两支共享同一份权重的高精度主副本，FP8 分支使用预量化的权重副本，避免运行时转换。</li>\n<li>阶段边界插入显式 cast kernel，cast 目标张量选在该阶段输出中尺寸最小者；cast 与后续 kernel 的 prologue 融合，减少一次 HBM 往返。</li>\n<li>分块解码时，块重叠区单独用 BF16 重算一遍边界帧，用高精度结果覆盖低精度接缝，代价是重叠区算力翻倍但只占块边界的一小部分。</li>\n</ul>\n<p>监控项必须能定位失败模式，而不只是看吞吐：帧间光流一致性（相邻帧运动向量的突变计数）、块间接缝处的像素梯度不连续度、以及同一提示词在 BF16 与低精度配置下的输出距离。这三项分别对应运动漂移、接缝伪影与整体质量退化。端到端时延要按阶段拆开统计，因为级联的瓶颈会在阶段间迁移：基础去噪降精度后，瓶颈很可能落到带宽受限的三维解码，此时继续压去噪精度收益递减。</p>\n<p>工程判断落在一点上：视频扩散的低精度部署不是“选一个精度”，而是“按级联段与采样步分配精度预算”，并把误差增益 <span>β_t/√(1-ᾱ_t)</span> 作为分配依据——高增益段保精度，低增益段换吞吐，转换点放在张量最小的边界，接缝用高精度重算兜底。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-18\">十八 · 级联扩散的精度边界：低精度能省在哪、会坏在哪</h3>\n<p>这套级联栈的量化收益并不均匀。基础生成器在低分辨率潜空间做多步去噪，每步一次时空注意力前向，权重与激活的带宽压力集中在潜变量与注意力工作集上；把这一级的矩阵乘降到 FP8 甚至 NVFP4，收益直接落在每步的访存与 Tensor Core 吞吐上，而低分辨率潜变量本身数值范围窄，量化误差被后续超分与插值稀释。真正脆弱的是三维 VAE 解码：它把潜变量还原为像素视频，输出直接进入人眼，帧间一致性对量化噪声极其敏感，低精度卷积与反卷积会把逐帧的微小偏差放大成闪烁与块间接缝。工程判断是：采样级激进、解码级保守，超分与插值介于两者之间，且必须与重叠帧拼接联合评估。</p>\n<p>累加精度决定误差是否被步数放大。扩散采样每步的残差更新可写成 <div class=\"formula\">$$z_{t-1}=\\frac{1}{\\sqrt{\\alpha_t}}\\Big(z_t-\\frac{\\beta_t}{\\sqrt{1-\\bar{\\alpha}_t}}\\,\\epsilon_\\theta(z_t,t,c)\\Big)+\\sigma_t\\xi$$</div> 其中 $\\epsilon_\\theta$ 的预测误差经 $\\beta_t/\\sqrt{1-\\bar{\\alpha}_t}$ 加权后进入下一步潜变量，多步迭代等价于误差沿采样链累积。若注意力与卷积的乘加以 FP8 输入、FP32 累加执行，单步误差可控；若累加也压到 FP16，长采样链末端会出现潜变量漂移，表现为运动轨迹偏移而非单帧噪声。Blackwell 的 tcgen05 与 TMEM 让累加器驻留片上、2-SM MMA 配对共享操作数，正是为了在不牺牲累加精度的前提下把低精度输入的吞吐拉满——用错这一层，省下的是带宽，赔上的是帧间一致性。</p>\n<p>失效条件集中在跨阶段耦合处。级联各阶段若被当作独立模型分别调优精度，会忽略潜变量分辨率跃升带来的显存峰值转移：低分辨率采样阶段的峰值由注意力工作集主导，超分阶段则由放大后的潜变量主导，解码阶段由像素块与重叠帧主导。长视频分块时，块间重叠帧是抑制接缝的唯一手段，而低精度解码会让重叠区的像素偏差在拼接处显影，重叠比例不足时接缝直接可见。流式逐块返回时，吞吐受三维解码带宽与注意力计算共同限制，量化解码虽降带宽却可能触发一致性返工。材料未给出精度实验与硬件档位，因此可核验的只有机制层面：量化必须按阶段分级，监控项应覆盖显存峰值、块间接缝与帧间运动一致性，任何一级的低精度都必须用重叠区一致性做验收，而非只看单帧指标。</p>\n<table class=\"mini\"><thead><tr><th>阶段</th><th>量化取向</th><th>主要代价</th><th>失效表现</th></tr></thead><tbody><tr><td>低分辨率扩散采样</td><td>FP8/NVFP4 输入，FP32 累加</td><td>每步注意力带宽</td><td>多步误差累积、轨迹漂移</td></tr><tr><td>时空超分</td><td>FP8 输入，保守累加</td><td>放大后潜变量显存</td><td>空间纹理与时间维不一致</td></tr><tr><td>帧插值</td><td>BF16/FP16 为主</td><td>相邻帧工作集</td><td>中间帧运动不连续</td></tr><tr><td>三维 VAE 解码</td><td>FP16/BF16，慎用低精度</td><td>像素块解码带宽</td><td>闪烁、块间接缝显影</td></tr></tbody></table>\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-19\">十九 · 显存账本的三类占用与峰值判据</h3>\n<p>在 Make-A-Video 的级联路径上，显存不是被一个“大模型”占满，而是被三类互不同步的占用叠加：权重常驻、激活工作集、以及跨阶段复用的条件与潜变量。权重部分相对静态——文本编码器、基础生成器、时空超分、帧插值、三维 VAE 解码器各自持有一份参数，量化到 FP8 或 NVFP4 只改变这一项的系数，不改变结构。真正决定能否跑起来的是激活工作集：基础生成器在低分辨率潜空间做多步去噪，每步一次时空注意力前向，工作集由潜变量张量本身加上注意力的 Q/K/V 与 softmax 中间结果构成；时空超分在空间与时间两维同时放大，激活尺寸按放大倍数的乘积增长；三维 VAE 解码则是把潜变量摊回像素体，激活峰值往往出现在解码的中间特征图上而非潜变量本身。</p>\n<p>可复算的判据是：把一次请求的显存峰值写成三项之和，逐项按张量形状乘出来，而不是按“模型多大”估。</p>\n<div class=\"formula\">$$M_{\\text{peak}} \\approx \\underbrace{\\sum_i P_i \\cdot b_w}_{\\text{权重}} + \\underbrace{\\max_j \\big(N_j \\cdot d_j \\cdot b_a\\big)}_{\\text{激活峰值}} + \\underbrace{C_{\\text{cond}} + Z_{\\text{block}}}_{\\text{复用与块潜变量}}$$</div>\n<p>其中 $P_i$ 是第 $i$ 个模块的参数个数，$b_w$ 是权重字节数（FP8 为 1，NVFP4 为 0.5 加缩放因子开销），$N_j$ 是第 $j$ 阶段的元素数，$d_j$ 是该阶段同时存活的中间张量份数，$b_a$ 是激活字节数。关键判断在于：$d_j$ 在时空注意力里不是 1，Q、K、V、注意力输出、残差至少五份同时存活，且时间维展开后 $N_j$ 随帧数线性增长。这就是为什么低分辨率基础生成器反而可能是峰值所在——它的步数最多，每步都要重建整套注意力工作集，而超分与插值只跑一次。</p>\n<p>工程代价落在批调度上：级联各阶段可独立批处理，但跨阶段流水线要管理潜变量传输，批大小不能由单阶段最优决定，而由“最高分辨率潜变量所在阶段”的峰值倒推。一个具体例子：若把基础生成器的批从 1 提到 4，注意力工作集近似线性翻四倍，而超分阶段只增加一份块潜变量，此时峰值从超分侧转移到基础侧，调度器必须按转移后的峰值重算并发上限，否则会在流水线中段 OOM。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-20\">二十 · KV 与跨步缓存的真实形态</h3>\n<p>视频扩散没有自回归解码那种逐 token 增长的 KV cache，但存在两类等价物。第一类是注意力内部的 K/V 张量：时空注意力在每个去噪步重算全部 K/V，步与步之间不保留，因此它不构成跨步缓存，而是每步的瞬时工作集——这正是“KV 显存”在扩散里的真实含义，代价是每步重算带来的带宽，而非容量。第二类是跨步可复用的条件与潜变量：文本条件嵌入在整条级联中被各级模块反复读取，属于只读复用；相邻去噪步的潜变量高度相关，属于可压缩复用。材料明确指出缓存复用点在于“跨步与跨块条件”，因此分页与压缩应当作用在这两类上，而不是照搬 LLM 的 PagedAttention 形态。</p>\n<p>可操作的伪代码思路是把条件嵌入与块级潜变量做成带引用计数的池：</p>\n<ul>\n<li>条件池：文本编码器输出一次，按请求 ID 挂引用；基础、超分、插值三级只读引用，不复制，释放由最后一个消费者触发。</li>\n<li>块潜变量池：长视频按块切分，块进入时分配、解码返回后回收；重叠帧作为相邻块的共享区，用偏移索引而非拷贝实现。</li>\n<li>跨步压缩：对相邻步潜变量做低秩或量化残差表示，仅当下一阶段确实需要历史步时才保留，否则丢弃。</li>\n</ul>\n<p>代价判断很直接：条件池把重复编码开销压掉，收益在文本编码器前向次数上；块潜变量池把峰值从“全视频”降到“单块加重叠”，收益在长视频可生成性上；跨步压缩省容量但增加解压带宽，若压缩比不足以抵消解压读带宽，反而拖慢采样。带宽瓶颈的位置由此确定：不在权重读取（权重可常驻、可量化），而在每步重算的注意力 K/V 写读与三维解码的像素写回，前者随帧数与分辨率平方增长，后者随输出像素体线性增长。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-21\">二十一 · 分块、重叠与卸载的联动</h3>\n<p>长视频分块是显存账本里唯一能主动改变峰值的杠杆。块大小与重叠比例未在材料中给出，但联动关系是确定的：单块潜变量尺寸决定激活峰值，重叠帧数决定接缝抑制能力，两者此消彼长。重叠不足则块间出现接缝与帧间跳变，重叠过多则相邻块重复计算，吞吐按重叠比例线性下降。可写成：</p>\n<div class=\"formula\">$$\\text{有效吞吐} \\propto \\frac{L_{\\text{block}}}{L_{\\text{block}} + L_{\\text{overlap}}},\\qquad M_{\\text{peak}} \\propto L_{\\text{block}} \\cdot H \\cdot W \\cdot d$$</div>\n<p>其中 $L_{\\text{block}}$ 为块帧数，$L_{\\text{overlap}}$ 为重叠帧数，$H \\cdot W$ 为该阶段潜空间的空间尺寸，$d$ 为同时存活的张量份数。这个式子说明：想在有限显存下加长视频，只能缩块或缩分辨率，而缩块必须靠重叠补一致性，吞吐必然让路。流式场景下逐块解码返回，SLO 由“单块解码时延”而非“整段视频时延”决定，因此块大小的选择实际上是首块时延与总吞吐的折中。</p>\n<p>卸载（offload）在这里的正确用法是把静态项挪出 HBM：文本编码器与帧插值模块在级联中只被调用一次或少数几次，可放在主机内存或按需换入；三维 VAE 解码器参数大但调用集中，适合在解码窗口前预取。不能卸载的是基础生成器的注意力工作集与当前块潜变量，因为它们每步都在读写。代价是 PCIe 往返延迟会插进流水线，若预取不与上一步采样重叠，卸载反而拉长端到端时延。一个具体例子：把帧插值模块整体卸载后，基础生成器可多容纳一个批次的块潜变量，峰值下降，但插值阶段的换入必须在超分输出后立即发起，否则该阶段成为串行气泡。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-22\">二十二 · HBM3e 容量怎么算，带宽瓶颈在哪</h3>\n<p>Blackwell 的 HBM3e 容量核算不看标称堆栈数，而看“可用容量减去不可回收项”。单卡可用容量要先扣掉：框架与通信缓冲、NCCL/NIXL 的注册内存、CUDA 上下文与 cuBLAS 工作区、以及为碎片预留的安全余量。剩下才是权重、激活、块潜变量与条件池能分的池子。可复算的顺序是：先按量化后的权重字节数锁定常驻项，再把剩余容量除以“单请求峰值激活”得到并发上限，最后用块大小反推可支持的最大帧数。</p>\n<div class=\"formula\">$$\\text{并发上限} = \\left\\lfloor \\frac{C_{\\text{avail}} - M_{\\text{weights}} - M_{\\text{comm}}}{M_{\\text{act,peak}} + M_{\\text{cond}} + M_{\\text{block}}} \\right\\rfloor$$</div>\n<p>带宽瓶颈有两处，且不在同一侧。第一处是时空注意力的每步重算：K/V 的写读量与 $N_j$ 成正比，步数越多，总带宽消耗越大，这部分是“算得越多、搬得越多”，与算术强度绑定。第二处是三维 VAE 解码的像素写回：输出像素体一旦落到 HBM 再被后续拼接读取，就是纯带宽开销，且随分辨率与帧数线性增长，算术强度低，是典型的带宽墙。判断哪处是主瓶颈的方法是比较两者的字节数与对应的计算量：若解码字节数远超注意力字节数而计算量很小，则解码侧是墙；若步数多、分辨率高使注意力字节数占优，则采样侧是墙。材料未给出分辨率与步数，因此只能落到机制判断：级联把高分辨率扩散换成了低分辨率扩散加一次超分加一次解码，正是把带宽压力从“多步高分辨率注意力”搬到“单次解码”，代价是解码侧的带宽墙更硬。</p>\n<p>精度方案对这两处的影响不同：权重与激活量化到 FP8/NVFP4 直接缩小注意力工作集与权重常驻，缓解容量；但三维解码若量化，需监控帧间一致性与块间接缝，因为解码是像素级还原，量化误差在时间维上会累积成闪烁。材料未给出精度实验，因此量化三维解码必须与一致性指标联合评估，不能只看单帧 PSNR。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-23\">二十三 · 一个可复算的显存预算示例</h3>\n<p>下面给出一个只依赖形状、不依赖实测数字的预算骨架，读者可代入自己的分辨率与步数复算。设基础生成器在潜空间尺寸 $h \\times w$、帧数 $f$ 上采样，注意力工作集按 $d=5$ 份张量计，激活字节 $b_a=2$（BF16）；超分阶段空间放大 $s$ 倍、时间放大 $t$ 倍；解码输出像素体为 $H \\times W \\times F$，像素字节 $b_p=2$。</p>\n<table class=\"mini\">\n<thead><tr><th>项</th><th>形状/系数</th><th>随什么增长</th><th>可否压缩</th></tr></thead>\n<tbody>\n<tr><td>基础注意力工作集</td><td>$h \\cdot w \\cdot f \\cdot d \\cdot b_a$</td><td>帧数线性、空间平方</td><td>量化激活、跨步复用</td></tr>\n<tr><td>超分激活峰值</td><td>$(s h)(s w)(t f) \\cdot d' \\cdot b_a$</td><td>放大倍数乘积</td><td>分块、按需重算</td></tr>\n<tr><td>块潜变量</td><td>$L_{\\text{block}} \\cdot h \\cdot w \\cdot b_a$</td><td>块帧数</td><td>池化、重叠索引</td></tr>\n<tr><td>解码像素体</td><td>$H \\cdot W \\cdot F \\cdot b_p$</td><td>输出像素总数</td><td>逐块解码、流式返回</td></tr>\n<tr><td>条件嵌入</td><td>与文本长度相关，材料未给</td><td>请求数</td><td>只读共享、引用计数</td></tr>\n</tbody>\n</table>\n<p>复算顺序：先填基础注意力项，因为它乘了步数之外的最大系数 $d$；再填超分项，注意 $s^2 t$ 的乘积往往让超分峰值超过基础峰值，此时块大小要按超分侧倒推；解码项单独看，若 $H \\cdot W \\cdot F$ 的像素体大于前两项之和，则必须逐块解码而不能整段解码。一个具体判断：当输出帧率被帧插值抬高后，$F$ 增大而潜变量帧数不变，解码像素体成为唯一随 $F$ 线性增长的项，因此高帧率输出的容量约束落在解码侧，而不是采样侧——这时把解码器参数卸载、把像素写回改成流式，比压缩注意力更有效。</p>\n<p>工程上还要留出跨阶段传输的余量：级联各阶段独立批处理时，阶段间潜变量要经 HBM 或跨卡传递，若超分与解码不在同一设备，潜变量传输会额外占用一份缓冲。材料未给出并行切分方式，因此预算里应显式保留一份“在途潜变量”份额，否则流水线一开就会在阶段边界处超限。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-24\">二十四 · 失败模式与监控项</h3>\n<p>显存账本最常见的错误是把级联各阶段当独立模型分别调优，忽略跨阶段潜变量分辨率与峰值的耦合：单看基础生成器能跑大 batch，单看解码器能跑高分辨率，拼在一起却在阶段边界处峰值叠加。第二个错误是分块重叠不足，为省显存缩块却不加重叠，接缝与帧间跳变在输出上可见，而监控里没有一致性指标就发现不了。第三个错误是在无精度实验的情况下直接对三维解码套低精度，量化误差在时间维累积成闪烁，单帧指标看不出来。</p>\n<p>监控项应覆盖四类：显存峰值按阶段打点，定位峰值究竟落在基础、超分还是解码；块间接缝一致性，用重叠区像素差与光流连续性衡量；帧间运动一致性，检查插值帧与相邻真实帧的速度场是否突变；端到端时延按块拆分，区分采样时延、超分时延与解码时延，判断带宽墙在哪一侧。这四项与前面的预算表一一对应：峰值打点验证 $M_{\\text{peak}}$ 的哪一项被低估，一致性指标验证重叠比例是否足够，时延拆分验证瓶颈是注意力重算还是像素写回。判断准则落在具体机制上——若解码时延占比随输出帧率上升而单调增大，则容量与带宽的约束已经从采样侧转移到解码侧，此时优化顺序应是先做逐块流式解码与解码器卸载，再考虑压缩注意力工作集。</p>\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-25\">二十五 · 级联栈的批处理边界：三阶段各自能批，但不能同批</h3>\n<p>Make-A-Video 的推理路径是一条三段级联：基础生成器在低分辨率潜空间做多步去噪，时空超分模块在空间与时间两维放大，帧插值模块补帧，最后三维 VAE 解码为像素。对调度器而言，这条链的关键性质是：三个阶段的计算形态不同、显存峰值不同、可批处理的维度也不同。基础生成器每步一次时空注意力前向，工作集由潜变量尺寸与注意力窗口决定；超分模块的输入是粗潜变量、输出分辨率更高，显存峰值随空间放大倍数上升；解码阶段是纯带宽受限的三维卷积/VAE 反传，几乎不产生新的条件依赖。因此合理的批处理策略是“阶段内批、阶段间流水”，而不是把整条链塞进一个统一 batch。</p>\n<p>具体机制上，调度器应为每个阶段维护独立的请求队列与独立的 batch 上限。基础生成器的 batch 上限由注意力工作集决定，超分阶段的上限由放大后的潜变量显存决定，解码阶段的上限由解码带宽与单块输出帧数决定。一个请求从文本编码器拿到条件嵌入后进入基础队列，完成全部采样步才释放给超分队列；超分队列攒够一批再统一放大；解码队列按块切分，逐块解码返回。伪代码思路如下：</p>\n<div class=\"formula\">$$\\text{batch}_s=\\Big\\lfloor \\frac{M_{\\text{free}}-M_{\\text{cond}}}{W_s}\\Big\\rfloor,\\quad W_s=\\alpha\\cdot H_s W_s T_s d + \\beta\\cdot A_s$$</div>\n<p>其中 $W_s$ 是阶段 $s$ 的单请求工作集，$H_s W_s T_s$ 为该阶段潜变量或像素块的时空尺寸，$d$ 为通道数，$A_s$ 为注意力工作集，$\\alpha,\\beta$ 为实测系数。这个式子的工程含义是：超分阶段的 batch 通常远小于基础阶段，因为放大后的潜变量尺寸是平方级增长；解码阶段的 batch 受限于输出帧缓冲，而不是算力。代价上，阶段内批处理提升吞吐，但阶段间流水引入潜变量在显存中的驻留与搬运，跨阶段传输本身消耗带宽——这正是级联栈调度最容易被忽略的一项开销。</p>\n<p>具体例子：一个 8 并发请求的场景，基础阶段可以 8 个一起采样，超分阶段因显存只能 2 个一批，于是 4 个请求在超分队列等待。若调度器不做阶段间流水，基础阶段空转等超分；若做流水，基础阶段继续接新请求，但显存里同时驻留“正在超分的粗潜变量”与“正在采样的新潜变量”，峰值显存上升。取舍点在于：流水度越高，吞吐越好，显存峰值越高，尾延迟越不可控。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-26\">二十六 · 连续批处理与 chunked prefill 在扩散采样上的映射</h3>\n<p>连续批处理在自回归解码里的含义是“每步重排 batch，完成的请求退出、新请求插入”。扩散采样没有自回归的 token 维度，但有等价的“步维度”：每个请求有固定的采样步数 $T$，各请求的步进度可以不同。把连续批处理映射过来，就是让调度器在每个采样步结束时重新组批，把步进度相同的请求拼在一起，把已完成的请求移出、把新请求插入。这样做的收益是 batch 利用率不随请求到达时间抖动而塌陷；代价是每步都要做一次组批决策，且不同请求的条件嵌入与潜变量尺寸必须兼容才能同批。</p>\n<p>chunked prefill 的映射更微妙。在 LLM 里它把长 prompt 的 prefill 切成小块与 decode 混批，避免长 prefill 阻塞 decode。在 Make-A-Video 的级联栈里，等价的长任务是“高分辨率超分块”与“长视频的分块解码”：一个超分块的计算量远大于一次基础采样步，若整块执行会长时间占住显存与 SM。chunked 化的做法是把超分块按时间维切成若干子块，每个子块与基础采样步混批执行，子块之间保留重叠帧。伪代码思路是维护一个按“计算量”排序的优先队列，每轮取若干基础采样步与一个超分子块组成混合 batch，子块完成后写回潜变量缓冲并释放显存。</p>\n<p>代价上，chunked 化降低了单次显存峰值与尾延迟，但增加了子块边界的重叠帧冗余计算：重叠帧既参与超分又参与拼接，计算量按重叠比例线性上升。具体例子：一个长视频被切成 $K$ 块、每块重叠 $r$ 帧，则总解码帧数为 $K\\cdot(F+(K-1)r)$ 量级，重叠比例直接吃吞吐。工程判断是：重叠比例应按接缝一致性监控指标动态调，而不是固定值——一致性达标就压低重叠，尾延迟超标就提高重叠换取更平滑的拼接。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-27\">二十七 · 优先级与抢占：谁该被切，切在哪里</h3>\n<p>级联栈的抢占比 LLM 更贵，因为扩散采样没有 KV cache 可以换出到主机内存再换入——潜变量本身就是全部状态，换出即意味着一次完整的显存搬运。因此抢占策略应尽量发生在阶段边界，而不是采样步中间。具体机制：调度器给每个请求打两级优先级，一级是 SLO 紧迫度（剩余时延预算），二级是阶段位置（基础/超分/解码）。当显存不足以接纳高优先级请求时，优先抢占“处于基础阶段且步进度靠前”的低优先级请求——因为它的潜变量最小、换出代价最低；避免抢占“处于超分或解码阶段”的请求，因为其工作集最大、换出即触发带宽尖峰。</p>\n<p>抢占的代价可以用一个简单的换出开销模型衡量：</p>\n<div class=\"formula\">$$\\text{cost}_{\\text{evict}}=2\\cdot\\frac{S_{\\text{latent}}}{B_{\\text{mem}}}+\\text{recompute}(t_{\\text{evict}})$$</div>\n<p>其中 $S_{\\text{latent}}$ 为被换出潜变量字节数，$B_{\\text{mem}}$ 为有效显存带宽，第二项为重新计算被丢弃步数的代价。这个式子说明：换出代价与潜变量尺寸成正比，与带宽成反比；在超分阶段换出一个高分辨率潜变量的代价可能是基础阶段的数倍。因此抢占决策不应只看优先级数值，而应看“换出代价 / 剩余时延收益”的比值。具体例子：两个低优先级请求，一个在基础阶段第 2 步、一个在超分阶段，高优先级请求到达时抢占前者，代价是重算两步低分辨率采样；抢占后者则要搬运放大后的潜变量，带宽开销直接反映在尾延迟上。</p>\n<p>另一个工程判断是：优先级不应只按请求到达时间排，而应按“级联阶段的可并行度”排。解码阶段是带宽受限、几乎不占 SM 的，可以与基础采样阶段混批而不显著拖慢后者；超分阶段是算力与显存双受限的，混批收益低。把解码请求当作“填充批”塞进基础采样的空隙，是压低尾延迟的低成本手段。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-28\">二十八 · 分离式预填/解码在级联栈里的对应物</h3>\n<p>分离式预填/解码在 LLM 里把 prefill 与 decode 放到不同资源池，因为两者分别是算力受限与带宽受限。Make-A-Video 的级联栈有一个天然的同构：基础生成器的多步采样是算力与注意力工作集受限的“预填型”工作，三维 VAE 解码是纯带宽受限的“解码型”工作。把这两段放到不同资源池，可以各自按最优 batch 与最优并行度配置，而不必在一套资源上做折中。</p>\n<p>具体机制：基础池按注意力工作集配置 batch 与并行切分，追求 SM 利用率；解码池按显存带宽配置 batch 与分块大小，追求带宽饱和。两池之间通过潜变量缓冲交接，交接的粒度是“一个请求的粗潜变量”或“一个超分后的潜变量块”。超分模块可以放在基础池侧（因为它需要条件嵌入与注意力），也可以独立成第三池。代价上，分离带来一次潜变量的跨池传输，传输量等于潜变量字节数；若两池在同一节点内，走显存到显存的拷贝；若跨节点，则走 NVLink 或网络，传输开销进入端到端时延。</p>\n<p>具体例子：流式输出场景下，解码池按块解码并逐块返回，基础池持续为新请求采样。若两池耦合在同一批里，解码的带宽尖峰会把基础采样的 SM 利用率拉低；分离后，解码池的带宽饱和与基础池的算力饱和可以同时发生。工程判断是：分离的收益在并发高、块多时最明显；并发低时，跨池传输的固定开销反而拖尾延迟，此时应退回单池混批。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-29\">二十九 · 尾延迟怎么压：从块粒度到 SLO 预算分配</h3>\n<p>级联栈的尾延迟来源有三处：最长采样步链的请求、最大超分块的执行、以及分块解码的最后一块。压尾延迟的手段不是提高平均吞吐，而是把这三处的“最长路径”切短。具体机制：第一，按剩余时延预算做步数预算分配——对临近 SLO 的请求，允许跳过帧插值模块或降低超分放大倍数，用质量换时延；第二，超分块按时间维切小，使单块执行时间不超过一个调度周期；第三，解码按块流式返回，首块优先，尾块与下一请求的基础采样混批。</p>\n<p>尾延迟的量化思路是把端到端时延分解为各阶段时延之和加上排队时延：</p>\n<div class=\"formula\">$$L_{\\text{e2e}}=\\sum_s \\big(L_s^{\\text{exec}}+L_s^{\\text{queue}}\\big),\\quad L_s^{\\text{queue}}\\approx\\frac{\\lambda_s W_s}{\\mu_s-\\lambda_s}$$</div>\n<p>其中 $\\lambda_s$ 为阶段 $s$ 的到达率，$\\mu_s$ 为服务率，$W_s$ 为单请求工作集。这个式子说明：排队时延在 $\\lambda_s$ 接近 $\\mu_s$ 时急剧上升，因此尾延迟的控制点是让每个阶段的利用率留出余量，而不是把某一阶段跑满。级联栈里最容易被跑满的是超分阶段——它的 batch 上限最低、工作集最大，是整条链的瓶颈阶段。工程判断是：容量规划应按超分阶段的 $\\mu_s$ 反推整链吞吐上限，基础阶段与解码阶段留出的余量用于吸收到达抖动。</p>\n<p>具体例子：一个流式长视频请求，其尾延迟由最后一块的解码时间决定。若把最后一块与下一请求的基础采样步混批，解码的带宽占用被基础采样的算力占用掩盖，尾延迟下降；代价是下一请求的首步被推迟，其首帧时延上升。这是一个明确的取舍：流式场景下首帧时延与尾块时延不能同时最优，调度策略应按 SLO 的类型（首帧优先还是完成优先）选择混批方向。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-30\">三十 · 跨阶段一致性监控与调度的耦合</h3>\n<p>调度决策会改变输出质量，这一点在级联栈里比在 LLM 里更直接：抢占导致的重算步数不同、chunked 化的子块边界不同、重叠比例不同，都会改变块间接缝与帧间运动一致性。因此监控项必须与调度参数联动，而不是事后独立评估。具体机制：为每个请求记录其调度轨迹（是否被抢占、重算了几步、子块边界落在哪、重叠比例多少），并把块间接缝一致性与帧间运动一致性作为调度器的反馈信号。当某类调度轨迹的一致性指标劣化时，调度器应调整该类请求的抢占策略或重叠比例。</p>\n<p>代价上，一致性监控本身要采样比对帧，消耗解码带宽与算力；监控粒度越细，开销越大。工程判断是：监控应落在块边界而非每帧，块边界的比对足以捕捉接缝与跳变；帧间一致性用抽帧比对即可，不必全帧比对。具体例子：一个被抢占两次的请求，其重算步数导致潜变量轨迹与未抢占请求不同，块边界处的运动连续性可能劣化；若监控发现该类轨迹的一致性指标偏低，调度器应优先保证这类请求不被抢占，或在其重算后追加一个短程一致性修正步。</p>\n<p>最终落在工程判断上：Make-A-Video 的级联栈把推理拆成可分别优化的阶段，但调度器不能把三个阶段当作独立模型分别调优——跨阶段的潜变量分辨率、显存峰值与一致性反馈是耦合的。批处理上限由瓶颈阶段（通常是超分）决定，尾延迟由最长路径（通常是最后一块解码）决定，抢占点应落在阶段边界而非采样步中间，一致性监控应作为调度参数的反馈而非事后报告。这三条约束共同决定了级联栈在有限显存与带宽下的实际吞吐上限。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-31\">三十一 · 级联栈的切分面：为什么不能只按参数量分</h3>\n<p>Make-A-Video 的推理路径是四级级联：文本编码器给出条件嵌入，基础生成器在低分辨率潜空间做多步扩散采样，时空超分模块在空间与时间两维放大，帧插值模块补帧，最后由三维 VAE 解码为像素。这条路径决定了并行切分的对象不是单一 Transformer，而是四个代价结构完全不同的阶段。基础生成器的瓶颈是时空注意力的工作集与迭代步数；超分模块的瓶颈是放大后潜变量的显存与带宽；帧插值模块的计算量小但需要相邻帧同时驻留；三维 VAE 解码则是纯带宽受限的卷积式还原。把四个阶段塞进同一个 TP 组是常见错误：TP 切的是注意力头与通道维，对 VAE 解码几乎没有收益，却把解码的激活切碎，迫使每块解码后做一次昂贵的 All-Gather 才能拼出完整像素块。</p>\n<p>正确的做法是按阶段选切分轴。基础生成器与超分模块用 TP 切注意力头，用 EP 切条件嵌入投影与前馈的专家式分片（若采用稀疏化），用 PP 把“低分辨率采样—超分—插值—解码”四级串成流水线，用 DP 复制整套权重承接并发请求。代价可以用一个简单的下界刻画：单步时延近似为计算项与通信项之和，</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\frac{F}{P_{\\text{eff}}\\cdot C} + \\frac{B}{W_{\\text{link}}} + L_{\\text{lat}}$$</div>\n<p>其中 F 是该步的浮点工作量，C 是单卡有效算力，B 是必须跨卡搬运的激活字节数，W 是链路带宽，L 是协议与内核启动延迟。TP 增大时第一项下降、第二项上升，交叉点就是该阶段的 TP 上限。对视频扩散而言，时空注意力的激活尺寸随帧数与分辨率增长，B 的增长快于 F，因此 TP 的有效上限比同参数量的语言模型更低。</p>\n<p>具体例子：把基础生成器的时空注意力按头切成 8 路 TP，每路持有 1/8 的头，注意力输出需要一次 All-Reduce 才能进入下一层。若潜变量分辨率提升一档，激活字节数按平方增长，而头数不变，All-Reduce 的通信量随之膨胀，此时继续加 TP 度只会让 T_step 的第二项主导，端到端时延反而变差。工程判断是：TP 度应随潜变量分辨率档位下调，而不是随卡数上调。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-32\">三十二 · 集合通信的三种形态与各自的代价位置</h3>\n<p>级联栈里出现的集合通信只有三类，但它们在视频扩散中的代价位置截然不同。All-Reduce 出现在 TP 的注意力输出与前馈输出处，通信量与激活大小成正比，且位于每步的关键路径上，直接叠加到采样步数上——步数越多，这项代价被乘得越狠。All-to-All 出现在 EP 的专家路由处，通信量取决于 token 到专家的分配偏斜；视频潜变量的 token 在时空维上分布不均，运动剧烈区域与静态背景的激活强度差异大，路由偏斜会放大尾延迟。All-Gather 出现在 PP 的阶段边界与 VAE 解码的拼块处，量最大但可以流水掩盖，前提是下一阶段的输入不依赖它的全部结果。</p>\n<p>以伪代码思路描述流水线边界的管理：</p>\n<ul>\n<li>阶段 k 完成一个微批的潜变量后，只发送该微批的切片，不等待整个批次；</li>\n<li>接收端在上一微批仍在解码时预取下一微批的条件嵌入与位置索引；</li>\n<li>块间重叠帧作为显式契约随切片一同传输，避免接收端重新计算重叠区。</li>\n</ul>\n<p>代价判断：All-Reduce 是延迟敏感项，必须压在关键路径最短的位置，通常用 NVLink 域内的环或树算法，把单次通信压到微秒级；All-to-All 是尾延迟敏感项，需要按专家负载做容量因子与冗余专家，否则个别重载专家决定整个微批的完成时刻；All-Gather 是带宽敏感项，适合与计算重叠，但重叠帧的重复传输会浪费带宽，重叠比例越高浪费越大。</p>\n<p>具体例子：长视频按块处理并保留重叠帧抑制接缝。若块边界处的 All-Gather 把重叠帧整段搬运，则重叠比例每提高一档，跨卡搬运字节数同比例上升；在链路带宽固定的前提下，这等价于用吞吐换一致性。工程上应把重叠帧只传一次并在接收端缓存复用，而不是每块重传。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-33\">三十三 · NVLink 5 与 NVSwitch：域内通信的边界在哪</h3>\n<p>Blackwell 世代的 NVL72 机柜把 GPU 通过 NVLink 5 与 NVSwitch 组成单跳全连接域，域内任意两卡之间的集合通信不经过主机网络。这对级联栈的意义是：TP 与 EP 应当被约束在这个域内，一旦跨出域，All-Reduce 与 All-to-All 就要落到网卡与交换机上，延迟抬升一个量级，采样步数多的扩散路径会被直接拖垮。判断规则很直接：把每步必须同步的通信全部关进 NVLink 域，把可以异步、可以流水、可以容忍百微秒级延迟的通信放到域外。</p>\n<p>域内带宽充裕不等于免费。NVSwitch 的聚合带宽被所有并发集合通信共享，当多个 DP 副本同时做 All-Reduce、同时有 PP 的 All-Gather 在跑，聚合带宽会被切分，单次通信的有效带宽下降。这就是为什么“卡越多越快”在扩散推理上经常失效：并行度提高带来的通信并发，吃掉了链路聚合带宽，T_step 的第二项不降反升。</p>\n<p>代价落到具体机制上：时空注意力的 All-Reduce 若跨 NVLink 域，单步时延增加的量级足以让多步采样的总时延翻倍；而三维 VAE 解码的拼块 All-Gather 若留在域内，则受聚合带宽切分影响，解码吞吐随并发 DP 副本数上升而下降。具体例子：一个 NVL72 域内跑多个 DP 副本，每个副本的基础生成器做 TP=4 的 All-Reduce，副本数增加时聚合带宽被均分，单副本的有效通信带宽下降，端到端吞吐的增长曲线提前饱和。工程判断是把 TP 组做小、把 DP 副本做多，让每步的同步通信量最小化，用副本数换吞吐而不是用 TP 度换单请求时延。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-34\">三十四 · NIXL 传输：跨阶段与跨节点的潜变量搬运</h3>\n<p>级联栈的 PP 边界与分离式部署（预填与解码分离、生成与解码分离）需要一种不经过框架序列化开销的显存到显存传输机制，NIXL 承担的就是这个角色：它把潜变量缓冲区的描述符在节点间交换，让接收端直接对远端显存发起读或写，绕开中间的主机内存拷贝与重复的框架调度。对视频扩散而言，这一点关键，因为阶段间搬运的是高维潜变量而非小尺寸的 token 嵌入，任何一次多余的拷贝都按潜变量字节数计费。</p>\n<p>传输代价可以写成：</p>\n<div class=\"formula\">$$T_{\\text{xfer}} = \\frac{S}{W_{\\text{nic}}} + \\frac{S}{W_{\\text{hbm}}}\\cdot k + L_{\\text{setup}}$$</div>\n<p>其中 S 是潜变量切片字节数，W_nic 是节点间链路带宽，W_hbm 是本地显存带宽，k 是拷贝次数，L_setup 是描述符交换与连接建立的一次性开销。NIXL 的价值在于把 k 压到最小并让 L_setup 在流水线中被摊薄；代价在于它要求接收端预留目标缓冲区，显存峰值因此上升，块大小与重叠比例必须与预留缓冲联动。</p>\n<p>具体例子：流式输出场景下逐块解码返回。基础生成器产出一块粗潜变量后，经 NIXL 直接写入解码节点的预留缓冲，解码节点在上一块尚未解完时已开始接收下一块。若不做预留而走主机中转，k 增大且引入主机内存带宽瓶颈，解码吞吐被搬运拖住；若预留过大，显存峰值上升，反而限制了并发块数。工程判断是：预留缓冲按单块潜变量尺寸加一份重叠帧计，重叠帧复用而非重传。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-35\">三十五 · 通信何时成为瓶颈：三个可观测的判据</h3>\n<p>不要凭感觉判断通信是否成为瓶颈，用三个判据。第一，单步时延中通信项占比：若 All-Reduce 与 All-Gather 的等待时间超过该步计算时间的固定比例，加卡不再缩短端到端时延，此时瓶颈已从算力转到链路。第二，聚合带宽占用率：多个 DP 副本与 PP 流水同时通信时，NVSwitch 聚合带宽接近饱和，单次通信有效带宽下降，吞吐曲线饱和先于时延曲线恶化。第三，尾延迟与偏斜：EP 的 All-to-All 若出现个别专家接收的 token 数远超均值，微批完成时刻由最慢的那一路决定，平均吞吐看起来正常而 SLO 已被尾延迟击穿。</p>\n<p>把这三个判据映射回级联栈：基础生成器的多步采样让 All-Reduce 的代价被步数放大，是最容易先撞墙的位置；时空超分的放大后潜变量让 All-Gather 的字节数按分辨率档位跃升，是第二个撞墙点；三维 VAE 解码的拼块传输在流式场景下与解码带宽竞争，是第三个。帧插值模块计算量小、通信量小，通常不是瓶颈，但它依赖相邻帧同时驻留，若显存被前两级占满，插值会被迫回退到分块重算，间接放大通信。</p>\n<p>具体例子：当潜变量分辨率提升一档，基础生成器的注意力激活按平方增长，All-Reduce 字节数随之增长，而单卡算力不变，T_step 的通信项占比跨过阈值，此时正确的动作是降低 TP 度、改用更多 DP 副本承接并发，并把超分与解码拆到独立节点用 NIXL 流水，而不是继续在同一 TP 组内加卡。反过来，若瓶颈在解码拼块的 All-Gather，则应缩小块尺寸、提高重叠帧复用率，把传输从关键路径挪到与解码重叠的位置。</p>\n<p>还有一个容易被忽略的耦合：级联各阶段被当作独立模型分别调优时，跨阶段潜变量分辨率与显存峰值的耦合会被忽略。基础生成器按自己的显存上限选块大小，超分模块按自己的上限选放大档位，两者相乘后超出单卡显存，迫使中间结果落回主机内存，k 增大、T_xfer 抬升，通信瓶颈以“显存不够导致的搬运”形式出现。工程判断是把块大小、重叠比例、放大档位与预留缓冲作为一组联合参数求解，而不是逐阶段独立取极值。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-36\">三十六 · 精度与切分的交互：低精度不改变通信拓扑，但改变阈值</h3>\n<p>材料未给出 NVFP4/FP8 的精度实验，因此这里只谈机制层面的交互，不给数字。量化降低的是计算项与激活字节数：权重与激活位宽下降后，All-Reduce 与 All-Gather 搬运的字节数同比例下降，T_step 的通信项随之下降，TP 的有效上限被推高。但量化同时改变数值稳定性，三维解码与时空注意力若用低精度，帧间一致性与块间接缝可能被放大，而这两项恰好是分块重叠机制要抑制的失败模式。也就是说，低精度让通信阈值变宽，却让一致性监控变严。</p>\n<p>工程上的处理是把精度方案与切分方案解耦评估：先在固定切分下测低精度对帧间一致性与接缝的影响，再在固定精度下测切分对通信项占比的影响，最后联合取点。监控项应包括显存峰值、块间接缝一致性、帧间运动一致性与端到端时延；其中接缝一致性与通信的重叠帧策略直接相关，帧间一致性则与注意力的数值精度相关。具体例子：若把三维 VAE 解码量化到低精度以降低拼块传输字节数，必须同时监控接缝处的像素跳变，因为解码是最后一级，误差不会被后续模块吸收。工程判断是：解码阶段优先保精度、通信优化靠 NIXL 与重叠帧复用而非量化；注意力与前馈阶段可以承受更低精度，因为它们的通信项才是 T_step 的主导项。</p>\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-37\">三十七 · 精度塌陷：从潜变量到像素的误差放大链</h3>\n<p>级联栈的精度风险不在单点，而在链路上。基础生成器输出的粗潜变量要经过时空超分放大空间与时间两维，再经帧插值补帧，最后三维 VAE 解码到像素。每一级都在放大上一级的误差：超分把低分辨率潜变量中的高频缺失当作待补信息，插值把相邻帧的相位误差当作运动来外推，VAE 解码把潜空间的微小偏移映射为可见的纹理漂移。材料未给出 NVFP4/FP8 实验，因此任何低精度方案都必须按“链路放大”而非“单算子误差”来评估。</p>\n<p>诊断上要把误差拆成可归因的量。对同一提示词、同一初始噪声，分别在高精度与目标精度下跑完整级联，逐级比对：粗潜变量的逐元素相对误差、超分后单帧的结构相似度、插值帧与真实相邻帧的光流残差、解码后块内与块间的像素差。伪代码思路是固定随机种子与采样步序列，只切换一级的精度，观察误差在哪一级开始非线性增长——若粗潜变量误差很小但解码后帧间跳变明显，问题在三维解码的累加顺序而非注意力。</p>\n<div class=\"formula\">$$\\varepsilon_{\\text{out}} \\approx \\sum_{k} \\left(\\prod_{j&gt;k} J_j\\right) \\varepsilon_k,\\quad J_j=\\frac{\\partial \\text{stage}_j}{\\partial \\text{stage}_{j-1}}$$</div>\n<p>系统代价落在重跑成本上：一次全链路精度对照要跑多组配置，每组都含多步时空注意力与三维解码，显存峰值由最高分辨率潜变量决定，吞吐被解码带宽拖住。工程判断是先把低精度限制在注意力与矩阵乘这类误差可被后续归一化吸收的位置，三维解码的最后一层保持高精度，因为它的输出直接可见且无法被下游修正。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-38\">三十八 · OOM 与显存峰值：峰值不在你以为的地方</h3>\n<p>级联栈的显存峰值由最高分辨率潜变量与注意力工作集共同决定，而不是由基础生成器的低分辨率采样决定。常见误判是把各阶段当独立模型分别调优：基础生成器按低分辨率潜变量估算显存，超分阶段却要在空间与时间两维同时放大，工作集骤增；长视频分块时若块大小与重叠比例未与显存上限联动，重叠帧本身就成为额外驻留。材料未给出具体分辨率与步数，因此只能按机制定位峰值来源。</p>\n<p>定位手段是分段打点：在每次注意力前向、每次超分放大、每次 VAE 解码块前后记录分配器峰值与驻留张量清单，区分“瞬时工作集”与“跨阶段驻留”。跨阶段驻留的典型是文本条件嵌入与低分辨率条件潜变量——它们被各级模块复用，复用减少重复编码开销，但也意味着生命周期跨越整个级联，不能被早释放。OOM 往往不是单块太大，而是复用张量与当前块工作集叠加超过上限。</p>\n<table class=\"mini\"><thead><tr><th>峰值来源</th><th>机制</th><th>代价</th><th>处置</th></tr></thead><tbody><tr><td>注意力工作集</td><td>时空注意力每步一次前向</td><td>随潜变量尺寸平方增长</td><td>按时空维切分，降块内分辨率</td></tr><tr><td>超分放大</td><td>空间与时间两维同时放大</td><td>工作集骤增，易触发 OOM</td><td>先空间后时间分步放大</td></tr><tr><td>重叠帧驻留</td><td>块间重叠用于抑制接缝</td><td>重叠比例直接吃显存</td><td>重叠比例与块大小联动调</td></tr><tr><td>复用条件张量</td><td>文本嵌入与低分辨率条件跨级复用</td><td>生命周期长，不可早释放</td><td>显式生命周期管理</td></tr></tbody></table>\n<p>回滚策略要前置：把块大小、重叠比例、超分放大顺序做成可热切换的配置项，OOM 触发时自动降块并保留重叠，而不是整请求失败。流式场景下逐块解码返回，单块 OOM 只影响该块的重试成本，端到端时延的损失可控。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-39\">三十九 · 批抖动与尾延迟：级联各阶段的批不同步</h3>\n<p>级联各阶段可独立批处理，但跨阶段流水线要管理潜变量传输，批抖动由此产生。基础生成器按低分辨率潜变量组批，超分阶段的工作集随分辨率上升，能承受的批更小；帧插值阶段又要等相邻帧齐备才能补帧。结果是上游批大、下游批小，中间出现排队与反压，尾延迟被最慢阶段钉住。材料未给出批大小与并发，因此诊断要落在阶段间队列深度与驻留时间上。</p>\n<p>定位方法是给每个阶段打三个量：入队等待时间、计算时间、下游反压时间。若某阶段计算时间稳定但入队等待长，瓶颈在上游产出速率；若计算时间方差大，瓶颈在该阶段内部的工作集波动。尾延迟的典型形态是长视频请求：块数多，每块都要走完整级联，任何一块的超分或解码抖动都会累积到端到端。</p>\n<div class=\"formula\">$$T_{\\text{e2e}}=\\sum_{b=1}^{B}\\left(T_{\\text{samp}}^{(b)}+T_{\\text{sr}}^{(b)}+T_{\\text{interp}}^{(b)}+T_{\\text{dec}}^{(b)}\\right)+T_{\\text{queue}}$$</div>\n<p>工程判断是把批按阶段解耦：上游按固定潜变量预算组批，下游按工作集上限重新切分，中间用有界队列吸收抖动；队列满时对上游做背压而不是无限堆积，避免显存被排队张量吃穿。尾延迟的 SLO 应按块而非按请求计，因为流式返回让首块时延与整段完成时延分离。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-40\">四十 · 接缝与运动不一致：静默降级的两种形态</h3>\n<p>静默降级指指标不报错但质量已退化。级联栈有两种典型形态。其一是块间接缝：长视频分块与重叠拼接，重叠不足时相邻块在边界处的纹理与亮度不连续，单帧看正常，连起来看跳变。其二是帧间运动不一致：帧插值在相邻帧间生成中间帧以提升帧率，但插值假设运动平滑，遇到快速运动或遮挡时会生成鬼影或方向错误的中间帧；超分模块若与插值联合评估不足，还会把插值的错误当作细节放大。</p>\n<p>监控要把一致性做成可计算的指标：块边界处取重叠区像素差与光流残差，帧间取相邻帧光流的二阶差分（加速度突变），并与同提示词高精度参考对比。伪代码思路是对每块解码后立即计算边界残差，超过阈值即标记该块并触发重叠比例上调重跑；对插值帧计算前后向光流一致性，不一致帧回退为不插值输出。</p>\n<p>代价是重跑与回退都消耗解码带宽：三维解码是吞吐瓶颈，重跑一块等于多一次解码。工程上把一致性检查放在解码后、返回前，用轻量残差代替全参考比对，避免监控本身成为尾延迟来源。静默降级的危险在于它不触发 OOM 也不报错，只能靠指标守住。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-41\">四十一 · 监控面与回滚路径：把配置做成可回退的开关</h3>\n<p>监控面要覆盖四类量：显存峰值与驻留张量清单（定位 OOM）、阶段队列深度与反压时间（定位批抖动）、块边界残差与帧间光流一致性（定位静默降级）、逐级精度对照的误差增长（定位精度塌陷）。材料未给出硬件档位与量化方案，因此监控不设绝对阈值，而以同配置高精度基线为参照做相对判定。</p>\n<p>回滚路径按代价从低到高排：先回退精度开关（三维解码最后一层恢复高精度），再回退块配置（降块大小、提重叠比例），再回退级联路径（关闭帧插值、只走超分），最后回退到整请求重跑。每一级回退都要能在不重启服务的前提下热切换，因为级联各阶段的配置耦合在潜变量分辨率与显存峰值上，重启会丢失在途块的状态。</p>\n<ul><li>精度回滚：只影响解码末层，重跑成本限于当前块。</li><li>块配置回滚：影响后续块，已在途块按旧配置完成。</li><li>路径回滚：关闭插值可立即降帧率换一致性，SLO 需按帧率重算。</li><li>整请求重跑：代价最高，仅在一致性指标持续越界时触发。</li></ul>\n<p>最后落在工程判断上：这套级联栈的失败模式几乎都源于“把阶段当独立模型调优”而忽略跨阶段耦合——显存峰值由最高分辨率潜变量与复用条件张量叠加决定，尾延迟由最慢阶段与块数决定，静默降级由重叠比例与插值假设决定。诊断的顺序应是先分段打点定位峰值与队列，再用逐级精度对照归因误差，最后用一致性指标守住返回前的质量门；回滚开关必须与这些打点同源，否则回滚本身就成了新的不确定性来源。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-42\">四十二 · 级联栈的失效边界：从潜变量耦合到块间接缝</h3>\n<p>这套级联路径的脆弱点不在单阶段内部，而在阶段之间的潜变量契约。基础生成器输出的粗潜变量必须与时空超分模块期望的分辨率、通道语义严格对齐；超分再放大后的潜变量又要满足帧插值模块的时域假设。任何一处不匹配都会以“静默降级”的形式出现：不报错、不崩溃，只是帧间运动变得黏滞或块边界出现色带。诊断这类问题的关键是把级联视为一条带状态传递的流水线，而不是三个独立模型。设第 <i>i</i> 级输出的潜变量为 <i>z<sup>(i)</sup></i>，其显存占用近似正比于 <i>B·C<sub>i</sub>·T<sub>i</sub>·H<sub>i</sub>·W<sub>i</sub></i>（批、通道、帧数、空间尺寸），则整条链的显存峰值并不出现在最贵的单级，而出现在“上一级输出尚未释放、下一级工作集已分配”的重叠窗口。工程上应把每级的输入输出潜变量做成显式契约（形状、dtype、时间对齐偏移），并在流水线切换点插入校验，而不是等三维 VAE 解码出像素后才发现接缝。</p>\n<p>长视频分块是第二类失效源。重叠帧的作用是让相邻块在时域上有共同上下文，但重叠比例与块大小必须与显存上限联动：块越大，单块潜变量与注意力工作集越大，显存峰值越高；重叠越少，接缝越明显。接缝的定量表征可以用相邻块在重叠区的潜变量差异来监控：<div class=\"formula\">$$s_{k}=\\frac{1}{|\\Omega_k|}\\sum_{f\\in\\Omega_k}\\big\\|z^{(k)}_{\\text{tail}}(f)-z^{(k+1)}_{\\text{head}}(f)\\big\\|_2$$</div>其中 <i>Ω<sub>k</sub></i> 是第 <i>k</i> 与 <i>k+1</i> 块的重叠帧集合。该指标在流式解码时逐块累积，一旦超过基线分布的分位阈值就触发告警——它比端到端人眼抽检更早、更便宜。代价是每块要多保留一份重叠潜变量，显存换一致性，重叠比例本质上是这个交换的旋钮。</p>\n<p>精度塌陷与批抖动常被混为一谈，但根因不同。前者来自量化：材料未给出 NVFP4/FP8 实验，若直接把三维解码或时空注意力降到低精度，误差会沿时间维累积，表现为帧间闪烁而非单帧失真——因为扩散采样每步都要一次时空注意力前向，低精度下的注意力分数扰动会在多步迭代中被放大。后者来自批调度：级联各阶段可独立批处理，但跨阶段流水线要管理潜变量传输，当超分阶段批大小与基础生成器不一致时，流水线会出现气泡，尾延迟被最长阶段拖住。监控应把“每级批大小、每级队列深度、潜变量传输时延”作为一等指标，而不是只看端到端 P99。回滚策略要按阶段粒度设计：精度回滚只需把解码与注意力切回高精度并重跑受影响块；批调度回滚则要冻结流水线深度、退回逐请求串行，牺牲吞吐换尾延迟稳定。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>定位手段</th><th>系统代价</th></tr></thead><tbody><tr><td>精度塌陷</td><td>帧间闪烁、块间色偏</td><td>逐块重跑高精度对比</td><td>解码带宽与算力回升</td></tr><tr><td>OOM</td><td>切换点显存尖峰</td><td>潜变量生命周期审计</td><td>块大小与重叠比例下调</td></tr><tr><td>批抖动</td><td>阶段队列深度振荡</td><td>逐级批大小对齐</td><td>吞吐下降换尾延迟</td></tr><tr><td>接缝</td><td><i>s<sub>k</sub></i> 越界</td><td>重叠区潜变量差异</td><td>重叠帧占用额外显存</td></tr></tbody></table>\n<p>尾延迟的根源在流式返回形态：逐块解码返回意味着首块时延与末块时延被同一套注意力计算与解码带宽约束，长视频的尾块还要等待前面所有块的条件传递。工程判断是：把 SLO 拆成“首块时延”与“块间间隔”两个独立目标，前者由基础生成器步数与首块解码决定，后者由超分与插值的流水线深度决定；只盯端到端平均值会掩盖尾块的排队放大。回滚的最后一层是块级重算：当某块的一致性指标越界，丢弃该块及其重叠区、用相邻块条件重新采样，代价是局部算力与显存峰值上跳，但避免了整段视频作废。</p>\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-43\">四十三 · 基准口径的拆解：把一次请求切成可计量的段</h3>\n<p>讨论 Make-A-Video 的推理基准，第一步不是找数字，而是确定“一次请求”在计量上到底由哪些段构成。它的推理路径是级联的：文本编码器给出条件嵌入，基础生成器在低分辨率潜空间做多步去噪，时空超分模块在空间与时间两维放大，帧插值模块补帧，最后由三维 VAE 解码为像素视频。这五段在延迟预算里的性质完全不同——文本编码是一次性的、与采样步数无关；基础生成器是步数乘以每步时空注意力前向；超分与插值各是一次或少数几次前向；三维解码则是带宽受限的像素级还原。把整条链压成一个端到端时延数字，等于把可优化的三段（采样步数、潜变量分辨率、块大小）和不可压缩的一段（解码带宽）混在一起，任何“提升”都无法归因。</p>\n<p>因此本卷建议的口径是分段打点，而不是单一指标。对每一段记录四个量：该段的墙钟时延、该段的显存峰值增量、该段触发的 HBM 读写字节数、以及该段是否与前后段可流水。级联结构的天然优势是段间只传递潜变量，传输量远小于像素，所以跨段流水在工程上可行；代价是流水会抬高显存峰值，因为相邻两段的潜变量必须同时驻留。这个耦合正是后面所有“不可比”数字的根源。</p>\n<div class=\"formula\">$$T_{\\text{e2e}}=\\sum_{s=1}^{S}T_{\\text{denoise}}(s)+T_{\\text{SR}}+T_{\\text{FI}}+T_{\\text{VAE}},\\quad M_{\\text{peak}}\\approx\\max_{k}\\big(M_{k}+M_{k+1}^{\\text{handoff}}\\big)$$</div>\n<p>公式右半句是显存口径的关键：峰值不由单段最大值决定，而由相邻两段交接时的驻留和决定。举例来说，若把基础生成器的潜变量分辨率提高一档，去噪段的注意力工作集上升，同时超分段接收的输入也变大，两个峰值叠加，端到端显存可能跳一个台阶，而单看任一段都看不出问题。这就是“把级联各阶段当作独立模型分别调优”这一失败模式在基准层面的具体表现。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-44\">四十四 · 硬件档位与精度：材料未给，口径必须先声明</h3>\n<p>该工作材料未给出硬件档位、也未给出 NVFP4/FP8 等精度方案，因此任何跨实现的吞吐对比都必须先声明三件事：算力档位（B200 单卡、GB200 NVL72 机架内、还是多机）、精度路径（三维解码与时空注意力是否量化、量化到哪一档）、以及是否启用了 tcgen05 与 TMEM 这类张量核心路径。这三项不声明，数字之间就没有公共分母。以 Blackwell 的工程现实看，时空注意力是典型的矩阵乘密集段，走 tcgen05 的 2-SM MMA 与走传统路径的吞吐差可以到数倍量级；而三维 VAE 解码是访存密集段，受益于张量核心的程度有限，反而对 HBM 带宽与 L2 命中更敏感。同一份“端到端加速比”若把解码段算进去，会被解码段的固定开销稀释；若只报去噪段，又会显得过于乐观。</p>\n<p>精度口径还有一层：视频扩散的潜变量迭代对数值误差的容忍度与语言模型不同，误差会在时间维上累积成帧间闪烁。若把注意力与解码量化到 FP8 甚至 NVFP4，需要监控的不是单帧 PSNR，而是跨帧一致性与块间接缝。材料未给出这类实验，所以本卷的口径是：任何声称的量化收益，必须同时报告帧间一致性指标，否则该收益不可采信。工程判断上，先量化注意力（收益大、误差可控），再评估解码（收益受带宽约束、误差直接落在像素上），这个顺序比反过来稳妥。</p>\n<table class=\"mini\"><thead><tr><th>口径项</th><th>必须声明的内容</th><th>不声明的后果</th></tr></thead><tbody><tr><td>硬件档位</td><td>单卡/机架、SM 代际、是否多机</td><td>吞吐比失去分母</td></tr><tr><td>精度路径</td><td>注意力与解码各自精度</td><td>加速比无法归因</td></tr><tr><td>批与并发</td><td>批大小、并发请求数、是否连续批处理</td><td>时延与吞吐混淆</td></tr><tr><td>分块参数</td><td>块大小、重叠帧数</td><td>显存峰值不可复现</td></tr></tbody></table>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-45\">四十五 · batch 与并发：级联各段的批语义并不相同</h3>\n<p>级联结构里，“批”不是一个统一概念。基础生成器的批是“并行的去噪轨迹数”，每条轨迹占一份潜变量与注意力工作集，批翻倍近似线性抬高显存；超分与插值段的批是“并行的块数”，其显存由最高分辨率潜变量决定，批的边际成本更高；三维解码段的批则受带宽约束，批增大提升的是带宽利用率而非算力利用率。因此一个常见的口径错误是：用去噪段的最优批大小去配置整条链，结果解码段成为瓶颈且显存被超分段吃满。正确做法是按段定批，段间用队列解耦，允许各段跑在不同批大小上。</p>\n<p>并发则是另一维。并发请求数决定的是队列深度与段间流水填充率，而不是单请求时延。流式场景下按块解码返回，首块时延（可类比 TTFT）由“文本编码 + 若干去噪步 + 一次超分 + 首块解码”构成，后续块的间隔（可类比 TPOT 的角色）由“单块去噪 + 解码”构成。这两个指标必须分开报：首块时延由固定开销主导，块间间隔由稳态吞吐主导，把两者平均成一个数会掩盖流式体验的真实瓶颈。材料未给出批大小与并发，所以本卷的口径是：报吞吐时必须附批大小与并发数，报时延时必须说明是首块还是稳态块间隔。</p>\n<ul><li>去噪段：批≈轨迹数，显存近似线性，适合小批多并发以填满流水。</li><li>超分段：批≈块数，显存由最高分辨率潜变量主导，宜小批。</li><li>解码段：批受带宽约束，增大批提升带宽利用率，需与块大小联动。</li><li>跨段流水：段间只传潜变量，传输量小，但相邻段驻留叠加抬高显存峰值。</li></ul>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-46\">四十六 · 指标怎么读：TTFT/TPOT 的类比与视频特有的量</h3>\n<p>把语言模型的 TTFT/TPOT 直接搬到视频扩散上会失真。视频的“首 token”应定义为第一个可播放的块解码完成，其成本包含文本编码、全部去噪步（因为首块必须走完采样才能超分解码）、一次超分与一次解码；而“后续 token”是后续块的解码间隔，其成本只含单块去噪与解码，不含文本编码。这意味着视频的首块时延对采样步数极其敏感——步数减半，首块时延近似减半，但稳态块间隔的改善幅度取决于单块去噪占比。若某优化只压缩了首块路径（例如缓存跨步条件），它对 TTFT 类指标好看，对吞吐几乎无贡献，这类数字不可与吞吐提升混谈。</p>\n<p>视频特有的量还有三个：帧间一致性、块间接缝、以及单位时间产出的有效像素。前两个是质量口径，第三个是吞吐口径。吞吐若只报“块/秒”而不报块的分辨率与帧数，跨实现不可比；若只报“像素/秒”而不报一致性，则可能奖励了那些靠降低重叠帧、放大块间跳变换来的吞吐。工程上应把吞吐与一致性放在同一张表里读：重叠帧增加会抬高显存与解码量、降低吞吐，但压低接缝；这是一条明确的权衡曲线，任何单点数字都必须标注它在这条曲线上的位置。</p>\n<div class=\"formula\">$$\\text{Throughput}_{\\text{eff}}=\\frac{N_{\\text{block}}\\cdot R_{\\text{px}}\\cdot F_{\\text{fps}}}{T_{\\text{e2e}}},\\quad \\text{Seam}\\propto f\\big(R_{\\text{overlap}}\\big)$$</div>\n<p>举例：若把重叠帧从若干帧减到更少，解码的像素总量下降，吞吐上升，但接缝风险上升；此时报出的吞吐提升不是“更快”，而是“用一致性换的”。材料未给出重叠比例，所以这类数字在本卷一律标注为口径未定，不作横向比较。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-47\">四十七 · 哪些提升不可比：四类典型陷阱</h3>\n<p>第一类是分辨率与帧数不同。级联路径的代价由潜变量分辨率与块数共同决定，一个在低分辨率短帧上测得的吞吐，与高分辨率长帧的吞吐不在同一坐标系。第二类是采样步数不同。去噪段是步数的线性函数，步数减半带来的时延下降会被误读为“系统优化”，实际是算法口径变化。第三类是分块策略不同。块大小与重叠比例同时影响显存峰值、解码量与接缝，三者耦合，任何只报其中一个参数的对比都不可复现。第四类是精度与硬件档位不同，前节已述。</p>\n<p>还有一个更隐蔽的陷阱：把级联各段分别测得的加速比相乘，当作端到端加速比。这只在各段时延占比已知且流水无气泡时成立。实际上段间交接有同步开销，流水填充有启动成本，相乘会系统性高估。正确做法是端到端实测，并用分段打点解释归因；若必须估算，应按段时延占比加权，而非简单相乘。工程判断上，凡是给出“各段加速比乘积”作为端到端结论的材料，其数字应降级为参考。</p>\n<ul><li>不可比：不同分辨率/帧数下的吞吐。</li><li>不可比：不同采样步数下的首块时延。</li><li>不可比：不同块大小与重叠比例下的显存峰值。</li><li>不可比：不同精度路径与硬件档位下的算力利用率。</li><li>不可比：分段加速比相乘得到的端到端数字。</li></ul>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-48\">四十八 · 落到可执行的口径表</h3>\n<p>综合以上，本卷对该工作的基准口径建议如下：端到端时延拆为首块时延与稳态块间隔两项分别报；吞吐报为“有效像素/秒”并附块分辨率、帧数与重叠比例；显存报峰值并注明是单段峰值还是相邻段交接峰值；功耗与带宽在材料未给硬件档位的情况下只作定性描述，即解码段受 HBM 带宽约束、去噪段受算力与注意力工作集约束。任何量化收益必须附帧间一致性与接缝指标。这套口径的价值不在于给出数字，而在于让不同实现之间的数字具备可归因性：当有人说“快了多少”，读者能立刻判断这个“快”来自步数、分辨率、重叠、精度还是真实的系统优化。</p>\n<p>最后落在一个具体机制上：级联路径的段间只传潜变量，这一设计使得“按段定批、段间队列解耦”成为可行的调度形态，但也使得显存峰值由相邻段驻留和决定。因此容量规划的第一约束不是单段显存，而是“最高分辨率潜变量段 + 其下游段的输入驻留”这一对组合；把块大小作为调节旋钮，先压这一对组合的峰值，再谈吞吐。材料未给出块大小与重叠比例，这一旋钮的具体取值只能由实测的显存上限反推，而不能从论文数字直接搬运。</p>\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-49\">四十九 · 迁移到别的模型：先看级联契约是否成立</h3>\n<p>这套推理方案的可迁移性不取决于它是不是扩散模型，而取决于一个更硬的条件：推理路径是否仍然是“低分辨率潜空间多步采样 → 空间/时间放大 → 像素解码”的级联契约。迁移到另一个视频生成器时，第一件要改的不是算子，而是阶段边界的定义。Make-A-Video 的级联里，时空超分模块复用低分辨率潜变量作为条件，帧插值模块复用相邻帧作为条件，三维 VAE 解码复用整块潜变量；三者共享同一套潜变量坐标系与时间索引。换到 CogVideoX 这类以 Transformer 为主干、时间维压缩方式不同的模型，潜变量的时间轴语义会变，超分模块如果仍按原来的帧对齐方式拼接，就会出现时间索引错位——不是精度问题，是语义错位。迁移时的判断标准很具体：新模型的潜变量是否在时间维上保持等间隔、空间维是否保持整数倍下采样比。若任一条件不成立，级联契约破裂，必须把超分与插值合并为单级放大，或改为在像素域做后处理，代价是显存峰值上移一个量级。</p>\n<p>第二个要改的是条件注入的位置。Make-A-Video 把文本条件通过图像文本对注入基础生成器，超分与插值模块只接收低分辨率条件与相邻帧，不重新编码文本。迁移到 CogVideoX 这类每级都带交叉注意力的架构时，若沿用“只编码一次”的做法，超分阶段会丢失文本对细节的约束，表现为放大后纹理漂移。工程上的改法是：文本嵌入在请求入口编码一次并缓存，各级模块通过轻量投影复用，而不是每级重跑文本编码器。这条改动的代价落在显存而非算力——缓存一份条件嵌入的显存开销远小于重复编码，但跨阶段流水线要管理这份缓存的生存期，块间切换时不能提前释放。</p>\n<div class=\"formula\">$$\\text{cascade cost}=\\sum_{s\\in\\{\\text{base},\\text{sr},\\text{fi}\\}} N_s\\cdot C_s(H_s,W_s,T_s)+C_{\\text{vae}}(H,W,T)$$</div>\n<p>式中 N_s 为各阶段采样或前向次数，C_s 为该阶段单次前向的注意力与卷积代价，H_s、W_s、T_s 为该阶段潜变量尺寸。迁移判断的实质是：换模型后哪一项主导。若新模型把时间维压缩得更狠，T_s 下降但空间维上升，三维解码的 C_vae 会成为新瓶颈；此时把优化预算从采样步数挪到解码分块策略上，比继续压步数更有效。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-50\">五十 · 迁移到别的领域：时间一致性的约束强度决定改法</h3>\n<p>迁到图像生成或单帧超分时，级联里时间维退化，帧插值模块整体删除，时空超分退化为空间超分，三维 VAE 退化为二维解码。这时方案仍然成立，但收益结构变了：原本靠分块重叠抑制接缝的机制不再需要，显存峰值由单张高分辨率潜变量决定，分块策略从“时间块+重叠帧”改为“空间瓦片+重叠边”。迁到音频或时序信号生成时，情况相反：时间维成为唯一维，空间维退化，时空注意力变成纯时间注意力，三维卷积退化为因果一维卷积。此时 Make-A-Video 的分块重叠机制仍然可用，但重叠比例要按感受野而非帧率来定，否则块边界会出现相位跳变。</p>\n<p>真正不适用的是强交互或强物理约束的领域，例如需要精确碰撞、刚体接触或多视角几何一致性的场景。这套级联的每一级都是生成式放大，超分与插值模块没有显式的几何约束项，块间重叠只能抑制视觉接缝，不能保证跨块的运动矢量连续。工程判断是：若下游任务对帧间位移有可测误差上限，这套方案只能作为候选生成器，后面必须挂一个显式的时序对齐或光流校正模块，代价是端到端时延增加一次光流估计与重采样。反过来，若下游只做人眼观看或粗粒度检索，级联的接缝抑制已经够用，不必引入校正。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-51\">五十一 · 规模上限在哪：三处代价的耦合决定天花板</h3>\n<p>规模上限不在参数量，而在三处代价的耦合方式。第一处是多步采样：每步一次时空注意力前向，步数与潜变量尺寸相乘构成基础生成器的总算力。第二处是三维解码：解码带宽随 H·W·T 线性增长，且解码通常在采样全部完成后一次性执行，显存峰值出现在解码前的潜变量驻留时刻。第三处是分块重叠：重叠帧不产生新内容却占用显存与解码带宽，重叠比例越高接缝越少，但有效吞吐按 1/(1+重叠比例) 衰减。三者耦合的后果是：想靠增大块尺寸提升吞吐，会推高单块潜变量显存；想靠减小重叠比例省显存，会放大接缝；想靠减步数省算力，会削弱超分模块的输入质量，反过来迫使超分承担更多放大责任。</p>\n<table class=\"mini\"><thead><tr><th>规模维度</th><th>主要受限代价</th><th>迁移时的改法</th></tr></thead><tbody><tr><td>分辨率提升</td><td>三维解码带宽与潜变量驻留显存</td><td>解码改为空间瓦片流式，瓦片间保留重叠边</td></tr><tr><td>时长提升</td><td>分块重叠带来的有效吞吐衰减</td><td>重叠比例按接缝可接受度定，不按固定值套用</td></tr><tr><td>帧率提升</td><td>帧插值模块的前向次数</td><td>插值倍率与超分联合评估，避免两级放大叠加伪影</td></tr><tr><td>并发提升</td><td>跨阶段流水线的潜变量传输与缓存生存期</td><td>各阶段独立批处理，条件嵌入按请求生命周期管理</td></tr></tbody></table>\n<p>判断规模上限的实操方法：固定分辨率与时长，只增并发，观察显存峰值是否由单块潜变量转为多请求潜变量叠加；若转为叠加，说明瓶颈从解码带宽移到显存容量，此时提升并发要靠跨阶段流水线而非加大批。材料未给出具体分辨率与步数，因此上限只能定性表述：这套级联的吞吐天花板由“采样步数 × 注意力工作集”与“解码带宽 × 重叠比例”两条曲线中较低者决定，迁移到新模型时先测这两条曲线，再谈扩容。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-52\">五十二 · 精度迁移的边界：低精度不能无差别套用</h3>\n<p>材料未给出 NVFP4/FP8 精度实验，因此精度迁移的判断只能落在机制层面。级联中三个阶段的数值敏感度不同：基础生成器的多步去噪对舍入误差有累积效应，单步误差会在后续步被放大；时空超分是单次前向放大，误差不累积但会直接体现在纹理上；三维 VAE 解码处于末端，误差直接进入像素域，且解码带宽大、天然适合低精度以省带宽。迁移到 Blackwell 时，合理的改法是分级量化：解码阶段优先低精度以换带宽，超分阶段保守量化并监控块间接缝，基础生成器维持较高精度或仅在注意力矩阵乘上做低精度、累加保持高精度。</p>\n<p>边界在于：若把三级全部压到同一低精度，帧间一致性会成为最先崩的指标，因为基础生成器的累积误差经超分放大后表现为帧间纹理跳变，而帧插值又会把这种跳变插成中间帧的伪运动。工程判断是：量化方案必须与一致性监控绑定，监控项至少包括块间接缝的像素差、相邻帧的光流残差、以及同一提示词多次采样的方差。没有这三项监控就上低精度，等于把失败模式藏进输出里。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-53\">五十三 · 不适用的部署形态：流式与离线共享同一套假设</h3>\n<p>这套方案默认请求是“文本进、短视频出”，级联各阶段串行且块间可重叠。迁到交互式编辑场景时不适用：用户逐帧修改或局部重绘要求生成器支持条件回填，而 Make-A-Video 的级联没有反向条件通路，超分与插值模块只接受前级输出，无法接受用户编辑后的中间结果。改法是把级联改为可中断流水线，在超分前暴露潜变量接口供外部写入，代价是每块都要做一次条件一致性校验，吞吐下降。</p>\n<p>迁到超长视频或直播式生成时，分块重叠机制的假设也会失效：重叠帧抑制接缝的前提是相邻块共享同一段潜变量上下文，块数增多后上下文窗口无法无限扩展，远端块与当前块的运动一致性只能靠全局条件嵌入维持，而全局嵌入的表达力有限。此时不适用的是“只靠重叠拼接”的做法，必须引入跨块的全局状态（如运动摘要或关键帧锚点），代价是每块解码前多一次全局状态读取与对齐。判断标准很直接：块数超过个位数后接缝指标是否随块数单调恶化，若是，说明重叠机制已到边界，该换全局状态方案而不是继续调重叠比例。</p>\n\n<h3 id=\"paper-make-a-video-text-to-video-generatio-2022-sec-54\">五十四 · 工程判断：迁移前先测三条曲线</h3>\n<p>把方案迁到新模型或新领域前，先测三条曲线，而不是先改代码。第一条是采样步数与输出质量的关系曲线，用来确定减步数的安全边界；第二条是块尺寸、重叠比例与接缝指标的关系曲线，用来确定分块参数；第三条是解码带宽与并发数的关系曲线，用来确定显存与吞吐的交换点。三条曲线都依赖具体硬件与精度方案，材料未给出数字，因此只能在目标平台上实测。测完之后再决定改哪里：若第一条曲线在低步数处陡降，优化预算应给超分模块而非采样；若第二条曲线在低重叠处陡升，说明接缝是主要失败模式，应优先做跨块全局状态；若第三条曲线在低并发处就饱和，说明解码是瓶颈，应优先做解码分块与低精度。</p>\n<p>最后落在一条具体机制上：这套级联的迁移成本主要不在算子替换，而在阶段边界的重新定义与监控项的重新绑定。换模型时，潜变量的时间索引语义与条件注入位置决定级联契约是否成立；换领域时，时间一致性的约束强度决定帧插值与重叠机制是保留、退化还是替换；换精度时，三级敏感度差异决定量化必须分级而非统一。三者任一判断错误，表现都不是精度下降，而是接缝、跳变与吞吐饱和同时出现——这也是迁移时最该先看的三个指标。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Make-A-Video: </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Text-to-Video Generation …</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2022 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Make-A-Video: Text-to-V… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称与规模</td></tr><tr><td>基线</td><td>材料未给出对比基线</td></tr><tr><td>主要结果</td><td>材料未给出定量结果；可核验的机制结论是级联式“低分辨率扩散＋时空超分＋帧插…</td></tr><tr><td>消融</td><td>材料未给出消融实验；可推断的消融维度包括是否使用时空超分、是否使用帧插值、…</td></tr><tr><td>局限</td><td>材料未给出失败模式与监控指标；从机制看，长视频分块拼接可能产生接缝，帧插值…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-make-a-video-text-to-video-generatio-2022 · 共 9 个片段</p>\n";break;}}})();
